    ["Enhances the quest log: quest levels (and optional quest IDs) in the titles, a larger frame, and a Parchment or Dark theme."] = "퀘스트 목록을 개선합니다: 제목에 퀘스트 레벨(선택 시 퀘스트 ID)을 표시하고, 창을 넓히며, 양피지 또는 어두운 테마를 적용합니다.",
