    ["|cffaaaaaaEnlarges the Tradeskill and Craft windows so the detail sits beside the recipe list, with a Parchment or Dark look.|r"] = "|cffaaaaaa제조 및 제작 창을 넓혀 상세 창이 제조법 목록 옆에 오게 하고, 양피지 또는 어두운 모양을 적용합니다.|r",
