    ["|cff888888Click a recipe's star (or right-click the recipe) to favourite it — the star turns gold.|r"] = "|cff888888제조법의 별을 누르거나 제조법을 오른쪽 클릭하면 즐겨찾기로 지정됩니다. 별이 금색으로 바뀝니다.|r",
