    ["Text Sizes"] = "글자 크기",
    ["Character"] = "캐릭터",
    ["World"] = "세계",
    ["Crisp portrait hit numbers"] = "선명한 초상화 피해 숫자",
    ["Renders the damage/heal numbers that flash on the Player/Pet portrait with a fixed, sharp font instead of Blizzard's blurry growing animation."] = "플레이어/소환수 초상화에 표시되는 피해/치유 숫자를 Blizzard의 흐릿하게 커지는 애니메이션 대신 고정된 선명한 글꼴로 표시합니다.",
    ["Hit number size"] = "피해 숫자 크기",
    ["Font size of the portrait hit numbers (when 'Crisp' is on)."] = "초상화 피해 숫자의 글꼴 크기입니다 (‘선명한’ 옵션이 켜져 있을 때).",
    ["Auto-select single gossip option"] = "대화 선택지가 하나면 자동 선택",
    ["Skips NPC dialog windows that only have a single option. Hold SHIFT to temporarily bypass."] = "선택지가 하나뿐인 NPC 대화 창을 건너뜁니다. SHIFT를 누르고 있으면 일시적으로 무시합니다.",
    ["Faster auto-loot"] = "빠른 자동 획득",
    ["Loots all items at once when auto-loot applies, instead of one by one."] = "자동 획득이 적용될 때 아이템을 하나씩이 아니라 한 번에 모두 획득합니다.",
    ["Max camera zoom"] = "최대 카메라 시야 거리",
    ["Raises the maximum camera zoom-out distance far beyond the default."] = "카메라를 뒤로 뺄 수 있는 최대 거리를 기본값보다 훨씬 크게 늘립니다.",
    ["Player & Target Frame"] = "플레이어 및 대상 프레임",
    ["Elite dragon border for your player frame, plus real health, threat display and the rare-elite border for the target and focus frames."] = "플레이어 프레임에 정예 용 테두리를 적용하고, 대상 및 주시 대상 프레임에 실제 생명력, 위협 수준 표시, 희귀 정예 테두리를 추가합니다.",
    ["Target & Focus Frame"] = "대상 및 주시 대상 프레임",
    ["|cffaaaaaaPuts the golden elite dragon (or the rare variants) around your player portrait — the look elite mobs have on the target frame.|r"] = "|cffaaaaaa플레이어 초상화에 황금색 정예 용(또는 희귀 변형)을 두릅니다 — 대상 프레임에서 정예 몹이 보여주는 모습입니다.|r",
    ["Frame style"] = "프레임 스타일",
    ["Elite (golden dragon)"] = "정예 (황금 용)",
    ["Rare-Elite (silver dragon)"] = "희귀 정예 (은색 용)",
    ["Rare (silver)"] = "희귀 (은색)",
    ["Off (default frame)"] = "끄기 (기본 프레임)",
    ["Cooldown Manager"] = "재사용 대기시간 관리자",
    ["A row of icons that shows the cooldowns of spells and trinkets you choose — like the retail cooldown manager."] = "직접 고른 주문과 장신구의 재사용 대기시간을 보여주는 아이콘 줄입니다 — 정식 서버의 재사용 대기시간 관리자와 같습니다.",
    ["Movable cooldown bars grouped however you like (procs, defensives, offensives ...) — like the retail cooldown manager."] = "원하는 대로 묶을 수 있는 이동 가능한 재사용 대기시간 바입니다 (발동 효과, 방어 기술, 공격 기술 ...) — 정식 서버의 재사용 대기시간 관리자와 같습니다.",
    ["|cffaaaaaaMovable cooldown bars grouped however you like — e.g. one for procs/buffs, one for defensive cooldowns, one for offensives. Pick or create a group below, then add spells/trinkets to it.|r"] = "|cffaaaaaa원하는 대로 묶을 수 있는 이동 가능한 재사용 대기시간 바입니다 — 예를 들어 발동 효과/강화 효과용 하나, 방어 기술용 하나, 공격 기술용 하나. 아래에서 그룹을 고르거나 새로 만든 다음 주문/장신구를 추가하십시오.|r",
    ["Cooldowns"] = "재사용 대기시간",
    ["Groups"] = "그룹",
    ["Edit group"] = "그룹 편집",
    ["New group"] = "새 그룹",
    ["Group %d"] = "그룹 %d",
    ["Delete group"] = "그룹 삭제",
    ["|cff888888Nothing in this group yet.|r"] = "|cff888888이 그룹은 아직 비어 있습니다.|r",
    ["Cooldown group '%s' unlocked. Drag spells/items onto it; |cff9b6cffdrag|r to move."] = "재사용 대기시간 그룹 '%s' 잠금 해제. 주문/아이템을 끌어다 놓으십시오. |cff9b6cff끌어서|r 옮길 수 있습니다.",
    ["Cooldown group '%s' locked."] = "재사용 대기시간 그룹 '%s' 잠김.",
    ["Group type"] = "그룹 종류",
    ["Buffs & Procs (only show while active)"] = "강화 효과 및 발동 효과 (활성 상태에서만 표시)",
    ["|cffaaaaaaIcons appear only while their buff/proc is on you; the bar is empty otherwise. Add the BUFF (e.g. Clearcasting) by name or ID.|r"] = "|cffaaaaaa해당 강화 효과/발동 효과가 걸려 있는 동안에만 아이콘이 나타나고, 그 외에는 바가 비어 있습니다. 강화 효과(예: 무결 시전)를 이름이나 ID로 추가하십시오.|r",
    ["|cffaaaaaaIcons show the cooldown of each spell/trinket.|r"] = "|cffaaaaaa각 주문/장신구의 재사용 대기시간을 아이콘에 표시합니다.|r",
    ["Size & offsets"] = "크기 및 오프셋",
    ["Extra settings"] = "추가 설정",
    ["Friends List"] = "친구 목록",
    ["Class-coloured friend names, class icons, faction accent and optional auto-accept for Battle.net invites."] = "친구 이름 직업 색상, 직업 아이콘, 진영 강조, Battle.net 초대 자동 수락 옵션을 제공합니다.",
    ["Dialog Popups"] = "알림 창",
    ["Restyles Blizzard's confirmation dialogs (logout countdown, delete item, resurrect, group invite) to match the dark look."] = "Blizzard의 확인 창(접속 종료 카운트다운, 아이템 삭제, 부활, 파티 초대)을 어두운 테마에 맞게 다시 꾸밉니다.",
    ["|cffaaaaaaRestyles Blizzard's confirmation dialogs — logout countdown, delete item, resurrect, group invite — to match the dark look.|r"] = "|cffaaaaaa접속 종료 카운트다운, 아이템 삭제, 부활, 파티 초대 등 Blizzard의 확인 창을 어두운 테마에 맞게 다시 꾸밉니다.|r",
    ["Accent strip"] = "강조 띠",
    ["Draws a thin accent gradient along the top edge of each dialog."] = "각 창의 위쪽 가장자리에 얇은 강조 그라데이션을 그립니다.",
    ["Addon Skins"] = "애드온 스킨",
    ["Restyles supported third-party addon windows to match the dark look: error list, quest tracker, loot browser, profiler and more."] = "지원되는 외부 애드온 창을 어두운 테마에 맞게 다시 꾸밉니다: 오류 목록, 퀘스트 추적기, 전리품 목록, 프로파일러 등.",
    ["|cffaaaaaaRestyles the windows of supported addons to the dark look. Skins apply when the addon is loaded; turning one off needs a /reload (the quest tracker restores live).|r"] = "|cffaaaaaa지원되는 애드온의 창을 어두운 테마로 바꿉니다. 스킨은 해당 애드온을 불러올 때 적용되며, 끄려면 /reload가 필요합니다 (퀘스트 추적기는 즉시 복원됩니다).|r",
    ["not loaded"] = "불러오지 않음",
    ["Map addon"] = "지도 애드온",
    ["Dark window skin"] = "어두운 창 스킨",
    ["Restyles the whole friends window dark with purple accents. Turning it off needs a /reload to restore Blizzard's frame."] = "친구 창 전체를 보라색 강조가 들어간 어두운 스타일로 바꿉니다. 끄면 Blizzard 프레임을 되돌리기 위해 /reload가 필요합니다.",
    ["Class color names"] = "직업 색상 이름",
    ["Colors each online friend's name by their class."] = "접속 중인 친구의 이름을 직업 색상으로 표시합니다.",
    ["Show class icons"] = "직업 아이콘 표시",
    ["Shows a class icon next to online WoW friends (in-game and Battle.net)."] = "접속 중인 WoW 친구 옆에 직업 아이콘을 표시합니다 (게임 내 및 Battle.net).",
    ["Class icon style"] = "직업 아이콘 스타일",
    ["Blizzard crests"] = "Blizzard 문장",
    ["Vulo Modern"] = "Vulo Modern",
    ["Vulo Style"] = "Vulo Style",
    ["Vulo icons"] = "Vulo 아이콘",
    ["Circles"] = "원형",
    ["Squares"] = "사각형",
    ["Show status dot"] = "상태 점 표시",
    ["A coloured dot after the name: green online, yellow away, red busy, grey offline."] = "이름 뒤에 색상 점을 표시합니다: 초록 접속 중, 노랑 자리 비움, 빨강 다른 용무 중, 회색 오프라인.",
    ["Show friend notes"] = "친구 메모 표시",
    ["Shows your saved note for the friend in grey under their name."] = "저장해 둔 친구 메모를 이름 아래에 회색으로 표시합니다.",
    ["Faction"] = "진영",
    ["Faction accent on realm line"] = "서버 줄에 진영 강조",
    ["Tints the realm/zone line red (Horde) or blue (Alliance)."] = "서버/지역 줄을 빨강(호드) 또는 파랑(얼라이언스)으로 물들입니다.",
    ["Faction row tint"] = "진영 행 색조",
    ["Adds a subtle red/blue background tint to each online friend's row."] = "접속 중인 친구의 각 행에 은은한 빨강/파랑 배경 색조를 더합니다.",
    ["Invites"] = "초대",
    ["Auto-accept Battle.net friend invites"] = "Battle.net 친구 요청 자동 수락",
    ["Automatically accepts incoming Battle.net friend requests."] = "들어오는 Battle.net 친구 요청을 자동으로 수락합니다.",
    ["Auto-accept group invites from friends"] = "친구의 파티 초대 자동 수락",
    ["Automatically joins a group when the invite comes from someone on your friends list."] = "친구 목록에 있는 사람이 초대하면 자동으로 파티에 참가합니다.",
    ["Class-coloured names, class icons, status dots, inline notes, faction tint and optional auto-accept."] = "직업 색상 이름, 직업 아이콘, 상태 점, 메모 표시, 진영 색조, 자동 수락 옵션을 제공합니다.",
    ["Highlight"] = "강조 표시",
    ["Proc glow (animated)"] = "발동 광채 (애니메이션)",
    ["Glow"] = "광채",
    ["Colored border"] = "색상 테두리",
    ["Highlight color"] = "강조 색상",
    ["Yellow"] = "노랑",
    ["Purple"] = "보라",
    ["White"] = "흰색",
    ["|cffaaaaaaA row of icons showing the cooldowns of the spells and trinkets you add. Type a spell/item name or ID below, shift-click a spell from your spellbook into the box, or unlock the bar and drag spells/items onto it.|r"] = "|cffaaaaaa추가한 주문과 장신구의 재사용 대기시간을 보여주는 아이콘 줄입니다. 아래에 주문/아이템 이름이나 ID를 입력하거나, 주문서에서 주문을 Shift-클릭해 입력란에 넣거나, 바의 잠금을 풀고 주문/아이템을 끌어다 놓으십시오.|r",
    ["Cooldown Manager: '%s' is not a known spell or item."] = "재사용 대기시간 관리자: '%s'은(는) 알 수 없는 주문 또는 아이템입니다.",
    ["Cooldown Manager: already tracking that."] = "재사용 대기시간 관리자: 이미 추적 중입니다.",
    ["Cooldown Manager: added %s."] = "재사용 대기시간 관리자: %s 추가됨.",
    ["Bar scale"] = "바 배율",
    ["Icon border thickness"] = "아이콘 테두리 두께",
    ["Class-colored border"] = "직업 색상 테두리",
    ["Border color..."] = "테두리 색상...",
    ["Bar background"] = "바 배경",
    ["Background color..."] = "배경 색상...",
    ["Show this bar"] = "이 바 표시",
    ["Only in a party (not raid)"] = "파티에서만 (공격대 제외)",
    ["Only in a raid"] = "공격대에서만",
    ["Only while solo"] = "혼자일 때만",
    ["Never (temporarily off)"] = "표시 안 함 (일시적으로 끄기)",
    ["Countdown text size"] = "카운트다운 글자 크기",
    ["Percent of the icon size."] = "아이콘 크기에 대한 백분율입니다.",
    ["Countdown text color..."] = "카운트다운 글자 색상...",
    ["Warn color under (sec)"] = "경고 색상 기준 (초)",
    ["Below this many seconds the countdown switches to the warn color; 0 turns the warn color off."] = "남은 시간이 이 값보다 적어지면 카운트다운이 경고 색상으로 바뀝니다. 0이면 경고 색상을 사용하지 않습니다.",
    ["Warn color..."] = "경고 색상...",
    ["Glow while ready"] = "준비되면 광채",
    ["A steady glow while the cooldown is ready - and, for spells, only while it is actually usable (enough mana etc.)."] = "재사용 대기시간이 끝나 준비된 동안 은은한 광채를 표시합니다. 주문의 경우 실제로 사용할 수 있을 때만 (마나가 충분한 경우 등) 표시됩니다.",
    ["Glow color"] = "광채 색상",
    ["Show keybinds"] = "단축키 표시",
    ["Shows the key the spell/item is bound to on your action bars. Macros are not matched; stance pages follow the main bar."] = "행동 단축바에 지정된 주문/아이템의 단축키를 표시합니다. 매크로는 인식하지 않으며, 태세 전환 페이지는 주 단축바를 따릅니다.",
    ["Keybind color..."] = "단축키 색상...",
    ["Keep inactive buffs visible (greyed out)"] = "비활성 강화 효과 계속 표시 (흐리게)",
    ["Icons stay in place when the buff runs out, just desaturated - the bar never jumps around."] = "강화 효과가 끝나도 아이콘이 흐려진 채 자리를 지켜서 바가 흔들리지 않습니다.",
    ["Add (name / ID)"] = "추가 (이름 / ID)",
    ["Tracked"] = "추적 중",
    ["|cff888888Nothing tracked yet.|r"] = "|cff888888아직 추적 중인 항목이 없습니다.|r",
    ["  |cff888888(item)|r"] = "  |cff888888(아이템)|r",
    ["Up"] = "위로",
    ["Icons per row"] = "한 줄당 아이콘 수",
    ["Growth direction"] = "확장 방향",
    ["Right"] = "오른쪽",
    ["Left"] = "왼쪽",
    ["Down"] = "아래쪽",
    ["Up (direction)"] = "위쪽",
    ["Only show while on cooldown"] = "재사용 대기 중일 때만 표시",
    ["Hides ready icons; they reappear when on cooldown."] = "준비된 아이콘을 숨기고, 재사용 대기 중이 되면 다시 나타납니다.",
    ["Show countdown text"] = "카운트다운 글자 표시",
    ["Show stacks"] = "중첩 수 표시",
    ["  |cffaa5555(other class)|r"] = "  |cffaa5555(다른 직업)|r",
    ["Unlock Mode"] = "잠금 해제 모드",
    ["|cffaaaaaaFor Blizzard's own Edit Mode: open it yourself via the game menu (|cffffffffEsc → Edit Mode|r). Blizzard blocks addons from starting it. Once it's open, your VuloUI windows appear in it automatically.|r"] = "|cffaaaaaaBlizzard 자체 편집 모드는 게임 메뉴에서 직접 여십시오 (|cffffffffEsc → 편집 모드|r). Blizzard는 애드온이 편집 모드를 시작하는 것을 막습니다. 편집 모드를 열면 VuloUI 창이 자동으로 함께 나타납니다.|r",
    ["Open Blizzard's Edit Mode"] = "Blizzard 편집 모드 열기",
    ["Open game menu for Blizzard's Edit Mode"] = "Blizzard 편집 모드를 위한 게임 메뉴 열기",
    ["Blizzard blocks addons from starting Edit Mode directly (it would taint). This opens the game menu — pick 'Edit Mode' there. Our windows then appear in it automatically."] = "Blizzard는 애드온이 편집 모드를 직접 시작하는 것을 막습니다 (보호된 코드가 오염됩니다). 이 버튼은 게임 메뉴를 엽니다 — 거기서 '편집 모드'를 선택하십시오. 그러면 VuloUI 창이 자동으로 함께 나타납니다.",
    ["Opens Blizzard's own Edit Mode (closes this window first). Our windows show up in it too."] = "Blizzard 자체 편집 모드를 엽니다 (이 창을 먼저 닫습니다). VuloUI 창도 그 안에 함께 나타납니다.",
    ["Can't open Edit Mode in combat."] = "전투 중에는 편집 모드를 열 수 없습니다.",
    ["This client has no Blizzard Edit Mode."] = "이 클라이언트에는 Blizzard 편집 모드가 없습니다.",
    ["Activate edit mode to move every VuloUI window at once."] = "이동 모드를 켜면 모든 VuloUI 창을 한 번에 옮길 수 있습니다.",
    ["|cffaaaaaaActivate edit mode to move every VuloUI window at once — cooldown bars, combat text, trackers, castbar, swing timer and more. It also opens automatically with Blizzard's Edit Mode.|r"] = "|cffaaaaaa이동 모드를 켜면 모든 VuloUI 창을 한 번에 옮길 수 있습니다 — 재사용 대기시간 바, 전투 문자, 추적기, 시전 바, 무기 공격 타이머 등. Blizzard 편집 모드를 열 때도 자동으로 함께 켜집니다.|r",
    ["|cff888888• Drag a purple box to move that window.|n• Hover a box, then use the arrow keys to fine-tune (SHIFT = 5px).|n• Right-click a box for exact X / Y.|n• |cffffffff/cdedit|r toggles this too.|r"] = "|cff888888• 보라색 상자를 끌어서 해당 창을 옮깁니다.|n• 상자 위에 마우스를 올린 뒤 방향키로 미세 조정합니다 (SHIFT = 5픽셀).|n• 상자를 우클릭하면 정확한 X / Y 값을 지정할 수 있습니다.|n• |cffffffff/cdedit|r 명령으로도 전환됩니다.|r",
    ["|cff44ff44Edit mode is ON.|r Close this window to reach the boxes, then lock again here or with /cdedit."] = "|cff44ff44이동 모드가 켜졌습니다.|r 이 창을 닫아야 상자를 만질 수 있습니다. 다시 잠그려면 여기서 끄거나 /cdedit를 사용하십시오.",
    ["Edit mode — move the cooldown bars"] = "이동 모드 — 재사용 대기시간 바 옮기기",
    ["Stop editing — lock the cooldown bars"] = "편집 종료 — 재사용 대기시간 바 잠그기",
    ["Unlocks just the cooldown bars so you can drag them. Arrow keys fine-tune; right-click a purple box for X/Y. (To move ALL VuloUI windows, use 'Unlock Mode' in Global.)"] = "재사용 대기시간 바만 잠금을 풀어 끌어서 옮길 수 있게 합니다. 방향키로 미세 조정하고, 보라색 상자를 우클릭하면 X/Y 값을 지정합니다. (모든 VuloUI 창을 옮기려면 전체 설정의 '잠금 해제 모드'를 사용하십시오.)",
    ["Edit mode — move all VuloUI windows"] = "이동 모드 — 모든 VuloUI 창 옮기기",
    ["Stop editing — lock all windows"] = "편집 종료 — 모든 창 잠그기",
    ["Unlocks every movable VuloUI window at once (cooldown bars, combat text, trackers …) so you can drag them. Arrow keys fine-tune; right-click a purple box for X/Y. Also opens with Blizzard's Edit Mode."] = "이동 가능한 모든 VuloUI 창(재사용 대기시간 바, 전투 문자, 추적기 …)의 잠금을 한 번에 풀어 끌어서 옮길 수 있게 합니다. 방향키로 미세 조정하고, 보라색 상자를 우클릭하면 X/Y 값을 지정합니다. Blizzard 편집 모드를 열 때도 함께 켜집니다.",
    ["right-click: settings"] = "우클릭: 설정",
    ["Edit mode — unlock all bars to move"] = "이동 모드 — 모든 바 잠금 해제",
    ["Stop editing — lock all bars"] = "편집 종료 — 모든 바 잠그기",
    ["Unlocks every cooldown bar at once so you can drag them all into place. Also opens automatically with Blizzard's Edit Mode. Anchoring is set per group in 'Anchor'."] = "모든 재사용 대기시간 바의 잠금을 한 번에 풀어 원하는 자리로 끌어다 놓을 수 있게 합니다. Blizzard 편집 모드를 열 때도 자동으로 함께 켜집니다. 고정은 그룹별로 '고정' 항목에서 설정합니다.",
    ["Cooldown edit mode |cff44ff44ON|r — drag any bar to move it. Toggle again to lock."] = "재사용 대기시간 이동 모드 |cff44ff44켜짐|r — 아무 바나 끌어서 옮기십시오. 다시 누르면 잠깁니다.",
    ["Cooldown edit mode |cffff5555OFF|r — all bars locked."] = "재사용 대기시간 이동 모드 |cffff5555꺼짐|r — 모든 바가 잠겼습니다.",
    ["Hide cooldowns under (sec)"] = "숨길 재사용 대기시간 기준 (초)",
    ["Cooldowns at or below this are ignored. 1.5 hides the global cooldown; raise it to also hide short cooldowns; 0 shows everything."] = "이 값 이하의 재사용 대기시간은 무시합니다. 1.5로 두면 공용 재사용 대기시간이 숨겨지고, 값을 올리면 짧은 재사용 대기시간도 숨겨집니다. 0이면 모두 표시합니다.",
    ["Reorder / remove"] = "순서 변경 / 제거",
    ["Move earlier"] = "앞으로 이동",
    ["Move later"] = "뒤로 이동",
    ["Stack / reagent position"] = "중첩 / 재료 위치",
    ["Stack / reagent size"] = "중첩 / 재료 크기",
    ["Stack / reagent color..."] = "중첩 / 재료 색상...",
    ["Bottom right"] = "오른쪽 아래",
    ["Bottom left"] = "왼쪽 아래",
    ["Top right"] = "오른쪽 위",
    ["Top left"] = "왼쪽 위",
    ["Show reagent counts"] = "재료 개수 표시",
    ["Shows each spell's OWN reagent count — Soul Shards on Soul Fire, Infernal Stone on Inferno, etc. Spells without a reagent show nothing. Needs 'Show stacks' on."] = "각 주문에 필요한 재료의 개수를 표시합니다 — 영혼의 불꽃에는 영혼의 조각, 지옥 소환에는 지옥의 돌 등. 재료가 필요 없는 주문에는 아무것도 표시되지 않습니다. '중첩 수 표시'가 켜져 있어야 합니다.",
    ["Anchor"] = "고정",
    ["Anchor to"] = "고정 대상",
    ["Pin this bar to a unit frame, the minimap, or another group's bar — it then moves with it. Drag the bar to detach."] = "이 바를 유닛 프레임, 미니맵 또는 다른 그룹의 바에 고정하면 함께 움직입니다. 바를 끌면 고정이 풀립니다.",
    ["Player Frame"] = "플레이어 프레임",
    ["Focus Frame"] = "주시 대상 프레임",
    ["Pet Frame"] = "소환수 프레임",
    ["None (free)"] = "없음 (자유 이동)",
    ["Cooldown Manager: can't anchor there — it would loop."] = "재사용 대기시간 관리자: 그곳에는 고정할 수 없습니다 — 순환이 생깁니다.",
    ["Side"] = "고정 방향",
    ["Below"] = "아래에",
    ["Above"] = "위에",
    ["Left of"] = "왼쪽에",
    ["Right of"] = "오른쪽에",
    ["X offset"] = "X 오프셋",
    ["Y offset"] = "Y 오프셋",
    ["Icon shape"] = "아이콘 모양",
    ["Square"] = "사각형",
    ["Rounded"] = "둥근 모서리",
    ["Icon zoom"] = "아이콘 확대",
    ["Cooldown swipe darkness"] = "대기시간 표시 어둡기",
    ["Only in combat"] = "전투 중에만",
    ["Only with a target"] = "대상이 있을 때만",
    ["Only with an attackable target"] = "공격 가능한 대상이 있을 때만",
    ["Hide while mounted"] = "탈것 탑승 중 숨기기",
    ["Only in instances"] = "인스턴스에서만",
    ["Dim icon while on cooldown"] = "재사용 대기 중 아이콘 어둡게",
    ["Flash when ready"] = "준비되면 번쩍임",
    ["|cffffffffCOOLDOWNS|r"] = "|cffffffff재사용 대기시간|r",
    ["Cooldowns: x=%.0f, y=%.0f"] = "재사용 대기시간: x=%.0f, y=%.0f",
    ["Cooldown Manager unlocked. Drag spells/items onto the bar to add. |cff9b6cffDrag|r the bar to move."] = "재사용 대기시간 관리자 잠금 해제. 주문/아이템을 바에 끌어다 놓으면 추가됩니다. 바를 |cff9b6cff끌어서|r 옮기십시오.",
    ["Cooldown Manager locked."] = "재사용 대기시간 관리자 잠김.",
    ["Saves named snapshots of your action bars, macros and keybindings, and restores them with one click."] = "행동 단축바, 매크로, 단축키 설정을 이름을 붙여 저장하고 한 번의 클릭으로 되돌립니다.",
    ["|cffaaaaaaSaves your complete bar setup (all action slots, macros, keybindings) as a named profile and restores it with one click — e.g. PvP and Raid layouts, or to copy a setup to a twink (account-wide storage).|r"] = "|cffaaaaaa전체 단축바 구성(모든 행동 슬롯, 매크로, 단축키)을 이름 붙인 프로필로 저장하고 한 번의 클릭으로 되돌립니다 — 예를 들어 PvP용과 공격대용 배치, 또는 부캐로 구성을 복사할 때 (계정 공용 저장).|r",
    ["Load"] = "불러오기",
    ["Save current setup"] = "현재 구성 저장",
    ["Please enter a profile name first."] = "먼저 프로필 이름을 입력하십시오.",
    ["|cff888888No profiles saved yet.|r"] = "|cff888888저장된 프로필이 없습니다.|r",
    ["Also restore macros"] = "매크로도 복원",
    ["Rewrites saved macros by name (existing ones are updated, missing ones created)."] = "저장된 매크로를 이름 기준으로 다시 씁니다 (기존 매크로는 갱신되고, 없는 매크로는 새로 만듭니다).",
    ["Also restore keybindings"] = "단축키도 복원",
    ["Load profile"] = "프로필 불러오기",
    ["Overwrite with current setup"] = "현재 구성으로 덮어쓰기",
    ["Replaces the selected profile with your current bars/macros/bindings."] = "선택한 프로필을 현재 단축바/매크로/단축키로 대체합니다.",
    ["Note: profile '%s' was saved on another class (%s)."] = "참고: 프로필 '%s'은(는) 다른 직업(%s)에서 저장되었습니다.",
    ["Flight Timer"] = "비행 시간 표시기",
    ["|cffff8800Flight route database not loaded.|r Fully restart WoW (a /reload is not enough after an update) so the flight times work."] = "|cffff8800비행 경로 데이터베이스를 불러오지 못했습니다.|r 비행 시간이 제대로 작동하도록 WoW를 완전히 재시작하십시오 (업데이트 후에는 /reload만으로는 부족합니다).",
    ["Show flight time bar"] = "비행 시간 바 표시",
    ["Shows destination and remaining time while on a taxi. The first flight of a route is learned, then you get a draining countdown."] = "비행 중에 목적지와 남은 시간을 표시합니다. 각 경로의 첫 비행에서 시간을 익히고, 그다음부터는 줄어드는 카운트다운을 보여줍니다.",
    ["Shows a progress bar with the duration of taxi flights. Unknown routes are learned on the first flight."] = "비행 시간을 나타내는 진행 바를 표시합니다. 모르는 경로는 첫 비행에서 익힙니다.",
    ["|cffaaaaaaShows a bar with destination and remaining time while on a taxi. The first flight of a route counts up and is saved; from then on you get a countdown.|r"] = "|cffaaaaaa비행 중에 목적지와 남은 시간을 보여주는 바를 표시합니다. 각 경로의 첫 비행에서는 시간이 올라가며 저장되고, 그다음부터는 카운트다운으로 표시됩니다.|r",
    ["(learning)"] = "(측정 중)",
    ["Flight: %s (%s)"] = "비행: %s (%s)",
    ["Print flight time to chat"] = "비행 시간 대화창에 출력",
    ["After landing, prints the measured flight time."] = "착륙 후 측정된 비행 시간을 출력합니다.",
    ["Reset learned times"] = "익힌 시간 초기화",
    ["Deletes all saved route durations."] = "저장된 모든 경로 시간을 삭제합니다.",
    ["Learned flight times reset."] = "익힌 비행 시간이 초기화되었습니다.",
    ["|cffaaaaaaLearned routes: %d|r"] = "|cffaaaaaa익힌 경로: %d개|r",
    ["|cffffffffFLIGHT TIME|r"] = "|cffffffff비행 시간|r",
    ["Flight timer: x=%.0f, y=%.0f"] = "비행 시간 표시기: x=%.0f, y=%.0f",
    ["Flight timer mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "비행 시간 표시기 이동 모드가 켜졌습니다. |cff9b6cff끌기|r 또는 |cff9b6cff방향키|r로 옮기십시오 (SHIFT = 5픽셀).",
    ["Flight timer mover disabled."] = "비행 시간 표시기 이동 모드가 꺼졌습니다.",
    ["Flight debug on — take a flight, the resolution appears in the chat."] = "비행 디버그 켬 — 비행하면 확인 결과가 채팅창에 표시됩니다.",
