    ["Red relic"] = "빨강 유물",
    ["Left click: remove this entry.\nRight click: remove this and all later entries."] = "좌클릭: 이 항목을 제거합니다.\\n우클릭: 이 항목과 이후 항목을 모두 제거합니다.",
    ["Click to record this color."] = "클릭하면 이 색상을 기록합니다.",
    ["Hotkey: %s"] = "단축키: %s",
    ["LazyVulo is disabled."] = "LazyVulo가 비활성화되어 있습니다.",
    ["|cffaaaaaaHelper for the Apexis Relic memory minigame (Ogri'la dailies). Record the flashing sequence with the buttons or hotkeys; the first icon is always your next click. Correct clicks are consumed automatically, wrong clicks are restored.|r"] = "|cffaaaaaa에펙시스 유물 기억력 미니게임(오그릴라 일일 퀘스트) 도우미입니다. 버튼이나 단축키로 깜박이는 순서를 기록하면 첫 번째 아이콘이 항상 다음에 누를 색입니다. 올바른 클릭은 자동으로 소모되고, 잘못된 클릭은 되돌려집니다.|r",
    ["|cffaaaaaaOpen manually with /lazyvulo or /lv.|r"] = "|cffaaaaaa/lazyvulo 또는 /lv 명령으로 직접 열 수 있습니다.|r",
