    ["A movable resource bar for your character. The power type follows your class automatically (Mana / Rage / Energy) — and for Druids it switches with your form: Bear = Rage, Cat = Energy, otherwise Mana."] = "캐릭터의 자원을 보여주는 이동 가능한 바입니다. 자원 종류는 직업에 맞춰 자동으로 정해지며 (마나 / 분노 / 기력), 드루이드는 변신 형태에 따라 바뀝니다: 곰 = 분노, 표범 = 기력, 그 외에는 마나.",
