    ["Block group invites from strangers"] = "모르는 사람의 파티 초대 차단",
    ["Auto-declines party/raid invites from players who are not in your guild or on your friends list."] = "길드원도 아니고 친구 목록에도 없는 플레이어의 파티/공격대 초대를 자동으로 거절합니다.",
    ["Block trades from strangers"] = "모르는 사람의 거래 차단",
    ["Auto-closes trade windows opened by players who are not in your guild or on your friends list. Trades you start yourself are not affected."] = "길드원도 아니고 친구 목록에도 없는 플레이어가 연 거래 창을 자동으로 닫습니다. 직접 시작한 거래에는 영향을 주지 않습니다.",
    ["|cffffd200[QoL]|r Blocked group invite from %s (not guild/friend)."] = "|cffffd200[QoL]|r %s의 파티 초대를 차단했습니다 (길드/친구 아님).",
    ["|cffffd200[QoL]|r Blocked trade from %s (not guild/friend)."] = "|cffffd200[QoL]|r %s의 거래를 차단했습니다 (길드/친구 아님).",
    ["Adds a tab to your spell book that lists the abilities you can still learn from your class trainer, grouped by level. Open the book icon below the spell schools."] = "주문서에 직업 교관에게서 아직 배울 수 있는 기술을 레벨별로 묶어 보여주는 탭을 추가합니다. 주문 계열 아래의 책 아이콘을 여십시오.",
    ["|cffaaaaaaAdds a tab to your spell book (the book icon on the side, below the spell schools) listing every ability you can still learn from your class trainer — grouped by status and coloured by level. No need to visit a trainer.|r"] = "|cffaaaaaa주문서에 탭(옆면의 주문 계열 아래에 있는 책 아이콘)을 추가해 직업 교관에게서 아직 배울 수 있는 모든 기술을 보여줍니다 — 상태별로 묶고 레벨별로 색을 입힙니다. 교관을 찾아갈 필요가 없습니다.|r",
    ["Available now"] = "지금 배울 수 있음",
    ["Available but Missing Requirements"] = "배울 수 있지만 선행 조건이 부족함",
    ["Upcoming"] = "앞으로 배울 기술",
    ["Not Yet Available"] = "아직 배울 수 없음",
    ["Missing Required Talents"] = "필요한 특성 없음",
    ["Already Known"] = "이미 배운 기술",
