    ["Cost: %s"] = "비용: %s",
    ["What can I train?"] = "무엇을 배울 수 있을까?",
    ["No results found"] = "결과가 없습니다",
    ["|cffffffffPOWER BAR|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffff자원 바|r\\n|cffaaaaaa드래그 또는 방향키|r",
    ["Power Bar mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Move' again to finish."] = "자원 바 이동 모드 활성화. |cff9b6cff보라색 상자를 드래그|r하거나 |cff9b6cff방향키|r를 사용하세요 (SHIFT = 5픽셀). 마치려면 ‘잠금 해제 / 이동’을 다시 클릭하세요.",
    ["Power Bar mover disabled."] = "자원 바 이동 모드 해제.",
    ["|cffaaaaaaResource bar that follows your class automatically (Mana / Rage / Energy). Druids switch with their form: Bear = Rage, Cat = Energy, otherwise Mana.|r"] = "|cffaaaaaa직업에 따라 자동으로 바뀌는 자원 바입니다 (마나 / 분노 / 기력). 드루이드는 변신 형태에 따라 전환됩니다: 곰 = 분노, 표범 = 기력, 그 외에는 마나.|r",
    ["|cffaaaaaaThe bar colour follows your current power type automatically (Mana = blue, Rage = red, Energy = yellow).|r"] = "|cffaaaaaa바 색상은 현재 자원 종류에 따라 자동으로 바뀝니다 (마나 = 파랑, 분노 = 빨강, 기력 = 노랑).|r",
