    ["UI not loaded. Likely a Lua error during init. Enable /console scriptErrors 1 and /reload."] = "UI를 불러오지 못했습니다. 초기화 중 Lua 오류가 발생했을 수 있습니다. /console scriptErrors 1 을 켜고 /reload 하세요.",
    ["Not possible in combat."] = "전투 중에는 할 수 없습니다.",
