    ["off"] = "꺼짐",
    ["Gold Tracker not active."] = "골드 추적기가 활성화되어 있지 않습니다.",
    ["|cffff5555Error while executing:|r %s"] = "|cffff5555실행 중 오류:|r %s",
    ["|cffff5555Event handler error (%s):|r %s"] = "|cffff5555이벤트 처리기 오류 (%s):|r %s",
    ["WARN: Module '%s' already registered."] = "경고: 모듈 ‘%s’은(는) 이미 등록되어 있습니다.",
    ["|cffff5555Error enabling module '%s':|r %s"] = "|cffff5555모듈 ‘%s’ 활성화 오류:|r %s",
    ["|cffff5555Error disabling '%s':|r %s"] = "|cffff5555‘%s’ 비활성화 오류:|r %s",
    ["Module '%s' disabled. /reload recommended for full effect."] = "모듈 ‘%s’이(가) 비활성화되었습니다. 완전히 적용하려면 /reload 를 권장합니다.",
    ["|cffff5555LibSharedMedia-3.0 not found, Media Registry will be skipped.|r"] = "|cffff5555LibSharedMedia-3.0 을 찾을 수 없어 미디어 등록을 건너뜁니다.|r",
    ["Profiles"] = "프로필",
    ["Manage profiles with different settings. A default profile can be assigned per class and is loaded automatically on login."] = "서로 다른 설정을 담은 프로필을 관리합니다. 직업별로 기본 프로필을 지정할 수 있으며 접속 시 자동으로 불러옵니다.",
    ["Active Profile"] = "사용 중인 프로필",
    ["You are currently using: |cff9b6cff%s|r  (Class: %s)"] = "현재 사용 중: |cff9b6cff%s|r  (직업: %s)",
    ["Switch Profile"] = "프로필 전환",
    ["Profile for this character"] = "이 캐릭터 전용 프로필",
    ["|cffaaaaaaPins a profile to THIS character only. At login it beats the class assignment and the account-wide selection - so every character can keep its own minimap, bars and window settings.|r"] = "|cffaaaaaa프로필을 이 캐릭터에만 고정합니다. 접속 시 직업 지정과 계정 전체 선택보다 우선하므로, 캐릭터마다 자신만의 미니맵, 바, 창 설정을 유지할 수 있습니다.|r",
    ["This character"] = "이 캐릭터",
    ["Create New Profile"] = "새 프로필 만들기",
    ["Name"] = "이름",
    ["Copy Settings From"] = "설정 복사 원본",
    ["- empty profile (defaults) -"] = "- 빈 프로필 (기본값) -",
    ["- none -"] = "- 없음 -",
    ["Create Profile"] = "프로필 만들기",
    ["|cffff5555Please enter a name.|r"] = "|cffff5555이름을 입력하세요.|r",
    ["|cffff5555Please enter a new name.|r"] = "|cffff5555새 이름을 입력하세요.|r",
    ["Error."] = "오류.",
    ["Manage Current Profile"] = "현재 프로필 관리",
    ["Share Profile"] = "프로필 공유",
    ["|cffaaaaaaExport the current profile as a text string - as a backup or to share it. Importing always creates a NEW profile and never overwrites anything.|r"] = "|cffaaaaaa현재 프로필을 텍스트 문자열로 내보냅니다. 백업하거나 공유할 때 사용합니다. 가져오기는 항상 새 프로필을 만들며 기존 설정을 덮어쓰지 않습니다.|r",
    ["Export as string"] = "문자열로 내보내기",
    ["Import from string"] = "문자열에서 가져오기",
    ["Copy the profile string (Ctrl+C):"] = "프로필 문자열을 복사하세요 (Ctrl+C):",
    ["Paste the profile string:"] = "프로필 문자열을 붙여넣으세요:",
    ["This is not a VuloClassicUI profile string."] = "VuloClassicUI 프로필 문자열이 아닙니다.",
    ["The profile string is damaged."] = "프로필 문자열이 손상되었습니다.",
    ["Profile '%s' imported. Activate it via 'Switch Profile'."] = "프로필 ‘%s’을(를) 가져왔습니다. ‘프로필 전환’에서 활성화하세요.",
    ["Manage Profiles"] = "프로필 관리",
    ["Delete..."] = "삭제...",
    ["Reset to defaults..."] = "기본값으로 초기화...",
    ["Delete profile '%s'? This cannot be undone."] = "프로필 ‘%s’을(를) 삭제할까요? 되돌릴 수 없습니다.",
    ["Reset profile '%s' to the default settings? This cannot be undone."] = "프로필 ‘%s’을(를) 기본 설정으로 초기화할까요? 되돌릴 수 없습니다.",
    ["Profile changed. Reload the UI now so every module picks it up?"] = "프로필이 변경되었습니다. 모든 모듈에 적용되도록 지금 UI를 다시 불러올까요?",
    ["|cffff5555Profile '%s' could not be loaded:|r %s"] = "|cffff5555프로필 ‘%s’을(를) 불러올 수 없습니다:|r %s",
    ["Rename to"] = "새 이름",
    ["Rename"] = "이름 변경",
    ["Delete Active Profile"] = "사용 중인 프로필 삭제",
    ["|cffff5555Default profile cannot be deleted.|r"] = "|cffff5555기본 프로필은 삭제할 수 없습니다.|r",
    ["Apply to Active Class"] = "현재 직업에 적용",
    ["Sets the current profile as the default for %s."] = "현재 프로필을 %s의 기본 프로필로 지정합니다.",
    ["'%s' is now the default profile for %s."] = "이제 ‘%s’이(가) %s의 기본 프로필입니다.",
    ["Per-class profile (quick setup)"] = "직업별 프로필 (빠른 설정)",
    ["|cffaaaaaaOne click: makes a profile named after your class (copied from the current one) and loads it for this class automatically. Run it once on each character — every class then keeps its own cooldown bars, frames and settings.|r"] = "|cffaaaaaa한 번의 클릭으로 현재 프로필을 복사해 직업 이름의 프로필을 만들고, 해당 직업에서 자동으로 불러오도록 설정합니다. 캐릭터마다 한 번씩 실행하면 직업마다 고유한 재사용 대기시간 바, 프레임, 설정을 유지합니다.|r",
    ["Set up a %s profile"] = "%s 프로필 만들기",
    ["'%s' is now the %s profile. |cffffff00/reload|r to apply."] = "이제 ‘%s’이(가) %s 프로필입니다. 적용하려면 |cffffff00/reload|r 하세요.",
    ["Profile Assignment per Class"] = "직업별 프로필 지정",
    ["Choose a default profile for each class. When logging in with a character of that class, the profile will be loaded automatically."] = "직업마다 기본 프로필을 선택하세요. 해당 직업의 캐릭터로 접속하면 프로필을 자동으로 불러옵니다.",
    ["Settings migrated to profile system (all settings are in profile '%s')."] = "설정이 프로필 시스템으로 이전되었습니다 (모든 설정은 프로필 ‘%s’에 있습니다).",
    ["|cffff5555Profile '%s' does not exist.|r"] = "|cffff5555프로필 ‘%s’이(가) 존재하지 않습니다.|r",
    ["Profile '%s' created%s."] = "프로필 ‘%s’이(가) 생성되었습니다%s.",
    [" (copy of '%s')"] = " (‘%s’의 복사본)",
    ["Name cannot be empty."] = "이름은 비워 둘 수 없습니다.",
    ["Profile already exists."] = "이미 존재하는 프로필입니다.",
    ["Default profile cannot be deleted."] = "기본 프로필은 삭제할 수 없습니다.",
    ["Profile does not exist."] = "프로필이 존재하지 않습니다.",
    ["Active profile deleted. Default loaded. /reload recommended."] = "사용 중인 프로필이 삭제되었습니다. 기본 프로필을 불러왔습니다. /reload 를 권장합니다.",
    ["Profile '%s' deleted."] = "프로필 ‘%s’이(가) 삭제되었습니다.",
    ["Default profile cannot be renamed."] = "기본 프로필은 이름을 변경할 수 없습니다.",
    ["New name already exists."] = "이미 같은 이름이 존재합니다.",
    ["Profile '%s' renamed to '%s'."] = "프로필 ‘%s’의 이름을 ‘%s’(으)로 변경했습니다.",
    ["Profile '%s' loaded. |cffffff00/reload|r recommended so all modules use the new settings."] = "프로필 ‘%s’을(를) 불러왔습니다. 모든 모듈이 새 설정을 사용하도록 |cffffff00/reload|r 를 권장합니다.",
    ["Settings imported from VuloFontBars."] = "VuloFontBars 설정을 가져왔습니다.",
    ["Settings imported from ArenaEnemyEdit."] = "ArenaEnemyEdit 설정을 가져왔습니다.",
    ["Settings imported from BetterBlizzQueue."] = "BetterBlizzQueue 설정을 가져왔습니다.",
    ["Settings imported from idTip."] = "idTip 설정을 가져왔습니다.",
    ["|cffff5555Profile module not loaded.|r"] = "|cffff5555프로필 모듈을 불러오지 않았습니다.|r",
