    ["Druid"] = "드루이드",
    ["Global Settings"] = "전체 설정",
    ["Global UI settings + profile management."] = "전체 UI 설정 + 프로필 관리.",
    ["UI Scale"] = "UI 배율",
    ["Manual UI scaling. 0.65 is smaller, 1.0 is default."] = "UI 배율을 직접 조정합니다. 0.65는 더 작고, 1.0이 기본값입니다.",
    ["Pixel Perfect"] = "픽셀 퍼펙트",
    ["UI Scale = %.4f (pixel perfect)"] = "UI 배율 = %.4f (픽셀 퍼펙트)",
    ["1080p Scale"] = "1080p 배율",
    ["UI Scale = 0.7111 (1080p)"] = "UI 배율 = 0.7111 (1080p)",
    ["1440p Scale"] = "1440p 배율",
    ["UI Scale = 0.5333 (1440p)"] = "UI 배율 = 0.5333 (1440p)",
    ["Max Camera Distance"] = "최대 카메라 거리",
    ["Maximum camera distance (CVar cameraDistanceMaxZoomFactor)."] = "최대 카메라 거리 (CVar cameraDistanceMaxZoomFactor).",
    ["Show Minimap Button"] = "미니맵 버튼 표시",
    ["Toggle the VuloClassicUI button on the minimap."] = "미니맵의 VuloClassicUI 버튼을 켜거나 끕니다.",
    ["Performance Display"] = "성능 표시",
    ["Show CPU Usage in Header"] = "헤더에 CPU 사용량 표시",
    ["Shows total CPU usage of all active addons (plus VuloClassicUI's own share) at the top of the config header.\n\n|cffaaaaaaRequires /reload after toggling.\n\nNote: Enables WoW's scriptProfile CVar, which costs ~3-5% performance — that's the price for WoW collecting this data at all.|r"] = "활성화된 모든 애드온의 총 CPU 사용량(VuloClassicUI 자체 사용량 포함)을 설정 헤더 상단에 표시합니다.\\n\\n|cffaaaaaa전환 후 /reload 가 필요합니다.\\n\\n참고: WoW의 scriptProfile CVar를 활성화하며, 약 3~5%의 성능을 소모합니다. WoW가 이 자료를 수집하기 위해 치르는 대가입니다.|r",
    ["Script profiling changed. /reload required for the CPU display to update."] = "스크립트 프로파일링이 변경되었습니다. CPU 표시를 갱신하려면 /reload 가 필요합니다.",
    ["Reload now"] = "지금 다시 불러오기",
    ["Later"] = "나중에",
    ["Shows a button on the minimap to quickly open VuloClassicUI. Shift+drag moves the button."] = "미니맵에 VuloClassicUI를 빠르게 여는 버튼을 표시합니다. Shift+드래그로 버튼을 옮길 수 있습니다.",
    ["UI is not loaded yet."] = "UI가 아직 준비되지 않았습니다.",
    ["|cffffffffLeft click:|r Open options"] = "|cffffffff왼쪽 클릭:|r 설정 열기",
    ["|cffffffffRight click:|r Quick module selection"] = "|cffffffff오른쪽 클릭:|r 모듈 빠른 선택",
    ["|cffffffffShift+drag:|r Move button"] = "|cffffffffShift+드래그:|r 버튼 이동",
    ["Open Options"] = "설정 열기",
    ["Show button on minimap"] = "미니맵에 버튼 표시",
    ["If off, the button is completely hidden."] = "끄면 버튼이 완전히 숨겨집니다.",
    ["Distance from center"] = "중심에서의 거리",
    ["Angle (degrees)"] = "각도 (도)",
    ["Tip: You can also move the button directly on the minimap — hold Shift and drag it to the desired position."] = "팁: 미니맵에서 버튼을 직접 옮길 수도 있습니다. Shift를 누른 채 원하는 위치로 드래그하세요.",
    ["Font Bars"] = "바 글꼴",
    ["Smaller font sizes for Player/Target/Pet Health & Mana bars, optionally hide TargetFrameBackground."] = "플레이어/대상/소환수 생명력 및 마나 바의 글꼴 크기를 줄이고, 선택적으로 TargetFrameBackground를 숨깁니다.",
    ["Health Bar Text"] = "생명력 바 글자",
    ["Font size on health bars (Player/Target/Pet)."] = "생명력 바의 글꼴 크기입니다 (플레이어/대상/소환수).",
    ["Power Bar Text"] = "자원 바 글자",
    ["Font size on mana/power bars."] = "마나/자원 바의 글꼴 크기입니다.",
    ["Pet Combat Feedback Text"] = "소환수 전투 정보 글자",
    ["Font size for 'Damage', 'Dodge', 'Miss' on the pet."] = "소환수에 표시되는 ‘피해’, ‘회피’, ‘빗나감’의 글꼴 크기입니다.",
    ["Only affect Player/Target/Pet bars"] = "플레이어/대상/소환수 바에만 적용",
    ["If off: all TextStatusBars in the UI are overridden with the sizes above (may interfere with other addons)."] = "끄면 UI의 모든 TextStatusBar가 위 크기로 덮어쓰기됩니다 (다른 애드온과 충돌할 수 있습니다).",
    ["Hide TargetFrame background"] = "TargetFrame 배경 숨기기",
    ["Permanently hides the dark background element of the TargetFrame."] = "TargetFrame의 어두운 배경 요소를 영구적으로 숨깁니다.",
    ["Target Frame"] = "대상 프레임",
    ["|cffaaaaaaAdds the modern Target/Focus frame extras the default Anniversary UI is missing - all cosmetic, no taint.|r"] = "|cffaaaaaa기본 Anniversary UI에 없는 최신 대상/주시 대상 프레임 기능을 추가합니다. 모두 외형 요소이며 보호된 코드를 오염시키지 않습니다.|r",
    ["Threat"] = "위협 수준",
    ["Numeric threat %"] = "숫자 위협 수준(%)",
    ["Shows your threat percentage on the target (and focus) above the frame, coloured by threat status."] = "대상(및 주시 대상)에 대한 위협 수준 비율을 프레임 위에 표시하고 위협 상태에 따라 색을 입힙니다.",
    ["Threat glow"] = "위협 발광 효과",
    ["Glows the target (and focus) frame in yellow/orange/red as your threat rises."] = "위협 수준이 오르면 대상(및 주시 대상) 프레임을 노랑/주황/빨강으로 빛나게 합니다.",
    ["Classification"] = "등급",
    ["Rare-Elite border"] = "희귀 정예 테두리",
    ["Shows the winged silver-dragon Rare-Elite border on rare-elite mobs."] = "희귀 정예 몹에 은빛 용 날개 모양의 희귀 정예 테두리를 표시합니다.",
    ["Class icon on player targets"] = "플레이어 대상에 직업 아이콘 표시",
    ["Shows the target's class crest on the frame when you target a player."] = "플레이어를 대상으로 지정하면 프레임에 대상의 직업 문장을 표시합니다.",
    ["Also apply to the Focus frame"] = "주시 대상 프레임에도 적용",
    ["Health"] = "생명력",
    ["Show real NPC health"] = "NPC 실제 생명력 표시",
    ["Shows the true health value on NPCs instead of the obfuscated percentage (enemy players stay %)."] = "NPC에게 가려진 비율 대신 실제 생명력 수치를 표시합니다 (적 플레이어는 비율로 유지).",
    ["Player Castbar"] = "플레이어 시전 바",
    ["Player castbar with two modes: Original (Blizzard bar extended) or Custom castbar (VUI style)."] = "두 가지 방식의 플레이어 시전 바: 기본형(Blizzard 바 확장) 또는 사용자 지정 시전 바(VUI 스타일).",
    ["|cffffffffCASTBAR|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffff시전 바|r\\n|cffaaaaaa드래그 또는 방향키|r",
    ["Castbar position: x=%.0f, y=%.0f"] = "시전 바 위치: x=%.0f, y=%.0f",
    ["|cff9b6cffMind Flay|r"] = "|cff9b6cff정신 채찍|r",
    ["Castbar mover active. |cff9b6cffDrag purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Test' again to finish."] = "시전 바 이동 모드 활성화. |cff9b6cff보라색 상자를 드래그|r하거나 |cff9b6cff방향키|r를 사용하세요 (SHIFT = 5픽셀). 마치려면 ‘잠금 해제 / 시험’을 다시 클릭하세요.",
    ["Castbar mover disabled."] = "시전 바 이동 모드 해제.",
    ["Castbar Variant"] = "시전 바 종류",
    ["Switch between Original (Blizzard bar extended) and Custom castbar (VUI style with icon, spell name below bar)."] = "기본형(Blizzard 바 확장)과 사용자 지정 시전 바(아이콘과 바 아래 주문 이름이 있는 VUI 스타일) 사이를 전환합니다.",
    ["Original (Blizzard bar extended)"] = "기본형 (Blizzard 바 확장)",
    ["Custom Castbar (VUI style)"] = "사용자 지정 시전 바 (VUI 스타일)",
    ["Castbar mode switched to |cff9b6cffOriginal|r. |cffffff00/reload|r recommended so the default bar works normally again."] = "시전 바 방식이 |cff9b6cff기본형|r으로 전환되었습니다. 기본 바가 다시 정상 작동하도록 |cffffff00/reload|r 를 권장합니다.",
    ["Castbar mode switched to |cff9b6cffVUI Style|r."] = "시전 바 방식이 |cff9b6cffVUI 스타일|r로 전환되었습니다.",
    ["|cffaaaaaaMode switch: A /reload may be required after switching so the default bar works normally again.|r"] = "|cffaaaaaa방식 전환: 전환 후 기본 바가 다시 정상 작동하려면 /reload 가 필요할 수 있습니다.|r",
    ["Show spell name"] = "주문 이름 표시",
    ["Show cast timer"] = "시전 시간 표시",
    ["Show channel ticks"] = "지속 시전 틱 표시",
    ["Shows vertical lines at tick points (Mind Flay, Drain Soul, Hellfire, etc.)"] = "지속 시전의 틱 지점에 세로선을 표시합니다 (정신 채찍, 영혼 흡수, 지옥불 등).",
    ["Show clip window"] = "지연 구간 표시",
    ["Shades the last bit of a channel (your latency) so you know when to recast and clip without losing the last tick - great for Mind Flay."] = "지속 시전의 마지막 구간(내 지연 시간)을 어둡게 표시해, 마지막 틱을 잃지 않고 다시 시전할 시점을 알려줍니다. 정신 채찍에 특히 유용합니다.",
    ["Shades your latency at the end of the bar: on channels the moment to recast without losing the last tick, on casts the spell-queue window where the next cast can already be pressed."] = "바 끝에 지연 시간을 어둡게 표시합니다. 지속 시전에서는 마지막 틱을 잃지 않고 다시 시전할 시점을, 일반 시전에서는 다음 시전을 미리 누를 수 있는 주문 대기열 구간을 나타냅니다.",
    ["Timer format"] = "시간 표시 형식",
    ["Remaining / total (1.5 / 2.0)"] = "남은 시간 / 전체 (1.5 / 2.0)",
    ["Remaining only (1.5)"] = "남은 시간만 (1.5)",
    ["Whole seconds (2)"] = "초 단위 정수 (2)",
    ["Show pushback"] = "시전 지연 표시",
    ["Briefly shows the time lost to spell pushback in red above the bar."] = "주문 시전 지연으로 잃은 시간을 바 위에 빨간색으로 잠깐 표시합니다.",
    ["Merge crafting casts"] = "제작 시전 합치기",
    ["When crafting several items in a row the bar shows a counter like 3/20 instead of single casts."] = "여러 개를 연속으로 제작할 때 개별 시전 대신 3/20 같은 진행 횟수를 바에 표시합니다.",
    ["Fill color"] = "채움 색상",
    ["Bar textures = the classic yellow/green art. Accent or class color tint a neutral bar instead."] = "바 텍스처 = 고전적인 노랑/초록 이미지입니다. 강조 색상이나 직업 색상은 무채색 바에 색을 입힙니다.",
    ["Bar textures (yellow/green)"] = "바 텍스처 (노랑/초록)",
    ["Accent color"] = "강조 색상",
    ["VUI Style: Position & Size"] = "VUI 스타일: 위치 및 크기",
    ["Unlock / Test"] = "잠금 해제 / 시험",
    ["Center Position"] = "중앙 위치",
    ["|cffaaaaaaTip: Hold |cffffffffSHIFT|r and drag the castbar with the left mouse button during a cast to move it. Or use 'Unlock / Test' for a permanent test bar for positioning.|r"] = "|cffaaaaaa팁: 시전 중에 |cffffffffSHIFT|r를 누른 채 왼쪽 마우스 버튼으로 시전 바를 드래그하면 옮길 수 있습니다. 또는 ‘잠금 해제 / 시험’으로 고정된 시험용 바를 띄워 위치를 맞추세요.|r",
    ["Show icon"] = "아이콘 표시",
    ["Icon Size"] = "아이콘 크기",
    ["Icon X Offset"] = "아이콘 X 오프셋",
    ["Icon Y Offset"] = "아이콘 Y 오프셋",
    ["Moves the icon horizontally. Negative = left, positive = right."] = "아이콘을 좌우로 옮깁니다. 음수 = 왼쪽, 양수 = 오른쪽.",
    ["Moves the icon vertically. Positive = up, negative = down."] = "아이콘을 위아래로 옮깁니다. 양수 = 위쪽, 음수 = 아래쪽.",
    ["Test only available in 'Custom Castbar' mode."] = "시험은 ‘사용자 지정 시전 바’ 방식에서만 사용할 수 있습니다.",
    ["Cooldown Pulse"] = "재사용 대기시간 펄스",
    ["Shows the icon of an expired cooldown as a brief pulsing animation in the screen center (based on Doom_CooldownPulse)."] = "재사용 대기시간이 끝난 주문의 아이콘을 화면 중앙에 잠깐 확대되는 애니메이션으로 표시합니다 (Doom_CooldownPulse 기반).",
    ["Cooldown Pulse unlock active — drag icon to move."] = "재사용 대기시간 펄스 잠금 해제 활성화 — 아이콘을 드래그해 옮기세요.",
    ["Cooldown Pulse unlock disabled."] = "재사용 대기시간 펄스 잠금 해제 종료.",
    ["Test Spell"] = "시험용 주문",
    ["Cooldown Pulse position reset."] = "재사용 대기시간 펄스 위치가 초기화되었습니다.",
    ["Unlock"] = "잠금 해제",
    ["Shows a test icon you can move around."] = "옮길 수 있는 시험용 아이콘을 표시합니다.",
    ["Test Pulse"] = "시험 펄스",
    ["Plays a test animation."] = "시험 애니메이션을 재생합니다.",
    ["Reset Position"] = "위치 초기화",
    ["Max Opacity"] = "최대 불투명도",
    ["Animation Scale"] = "애니메이션 배율",
    ["Fade-In Time (s)"] = "나타나는 시간 (초)",
    ["Hold Time (s)"] = "유지 시간 (초)",
    ["Fade-Out Time (s)"] = "사라지는 시간 (초)",
    ["Show Before Available (s)"] = "사용 가능 전 표시 (초)",
    ["Triggers the animation X seconds BEFORE the cooldown expires. 0 = exactly at cooldown end."] = "재사용 대기시간이 끝나기 X초 전에 애니메이션을 시작합니다. 0 = 대기시간이 끝나는 시점.",
    ["Spell Filter"] = "주문 필터",
    ["Show spell names"] = "주문 이름 표시",
    ["Shows the name of the spell under the icon."] = "아이콘 아래에 주문 이름을 표시합니다.",
    ["Invert filter (whitelist instead of blacklist)"] = "필터 반전 (차단 목록 대신 허용 목록)",
    ["Off: List = ignored spells. On: List = show ONLY these spells."] = "끔: 목록 = 무시할 주문. 켬: 목록 = 이 주문만 표시.",
    ["Spell List (comma-separated)"] = "주문 목록 (쉼표로 구분)",
    ["Spell names exactly as in-game, comma-separated. Spell IDs also work."] = "게임에 표시되는 그대로의 주문 이름을 쉼표로 구분해 입력하세요. 주문 ID도 사용할 수 있습니다.",
    ["Arena Frames"] = "투기장 프레임",
    ["Enhances the Arena enemy frames: move/scale, class colors, class icons, PvP trinket CD, DR tracking, castbar, drag&drop layout."] = "투기장 적 프레임을 개선합니다: 이동/배율, 직업 색상, 직업 아이콘, PvP 장신구 재사용 대기시간, 효과 감소(DR) 추적, 시전 바, 드래그 앤 드롭 배치.",
    ["|cffff5555ArenaFrames submodule error:|r %s"] = "|cffff5555ArenaFrames 하위 모듈 오류:|r %s",
    ["|cffff5555Arena submodule OnEnable error:|r %s"] = "|cffff5555투기장 하위 모듈 OnEnable 오류:|r %s",
    ["Layout"] = "배치",
    ["Class Color"] = "직업 색상",
    ["PvP Trinket"] = "PvP 장신구",
    ["DR Tracker"] = "효과 감소(DR) 추적기",
    ["Castbar"] = "시전 바",
    ["|cffffffffArena Frames|r"] = "|cffffffff투기장 프레임|r",
    ["|cffaaaaaaClick + drag\nMouse wheel = scale|r"] = "|cffaaaaaa클릭 + 드래그\\n마우스 휠 = 배율|r",
    ["Arena Frames position saved."] = "투기장 프레임 위치가 저장되었습니다.",
    ["|cff9b6cffArenaFrames Unlock|r  |cffaaaaaa(Scale: %.2f)|r"] = "|cff9b6cffArenaFrames 잠금 해제|r  |cffaaaaaa(배율: %.2f)|r",
    ["|cffaaaaaaClick + drag\nMouse wheel = scale\nCurrent: %.2f|r"] = "|cffaaaaaa클릭 + 드래그\\n마우스 휠 = 배율\\n현재: %.2f|r",
    ["|cff9b6cffArenaFrames Unlock|r"] = "|cff9b6cffArenaFrames 잠금 해제|r",
    ["Drag the purple overlay above the frames to move.\nMouse wheel on overlay = scale. /vcui arenaframes to finish."] = "프레임 위의 보라색 오버레이를 드래그해 옮기세요.\\n오버레이 위에서 마우스 휠 = 배율. 마치려면 /vcui arenaframes 를 입력하세요.",
    ["Unlock active. Click + drag the purple overlay to move."] = "잠금 해제 활성화. 보라색 오버레이를 클릭 + 드래그해 옮기세요.",
    ["Unlock disabled."] = "잠금 해제 종료.",
    ["ArenaPlayer"] = "ArenaPlayer",
    ["Reset position"] = "위치 초기화",
    ["Position reset."] = "위치가 초기화되었습니다.",
    ["In unlock mode a purple overlay appears above the frames. Click + drag to move, mouse wheel to scale."] = "잠금 해제 상태에서는 프레임 위에 보라색 오버레이가 나타납니다. 클릭 + 드래그로 옮기고 마우스 휠로 배율을 조절하세요.",
    ["Layout (Order)"] = "배치 (순서)",
    ["Order of the arena frames. Use up/down to move slots 1-5."] = "투기장 프레임의 순서입니다. 위/아래로 1~5번 자리를 옮기세요.",
    ["|cff9b6cff%d.|r  Arena Slot %d"] = "|cff9b6cff%d.|r  투기장 자리 %d",
    ["Move up"] = "위로 이동",
    ["Move down"] = "아래로 이동",
    ["Spacing between frames"] = "프레임 간 간격",
    ["Grow direction"] = "확장 방향",
    ["Downward"] = "아래쪽",
    ["Upward"] = "위쪽",
    ["Reset order"] = "순서 초기화",
    ["Class Visuals"] = "직업 표시",
    ["Class-colored health bars"] = "직업 색상 생명력 바",
    ["Colors the health bar in the player's class color."] = "생명력 바를 플레이어의 직업 색상으로 칠합니다.",
    ["Class-colored name"] = "직업 색상 이름",
    ["Class icon instead of portrait"] = "초상화 대신 직업 아이콘",
    ["Replaces the 3D portrait with a class symbol."] = "3D 초상화를 직업 상징으로 대체합니다.",
    ["PvP Trinket Tracker"] = "PvP 장신구 추적기",
    ["Show PvP trinket cooldown"] = "PvP 장신구 재사용 대기시간 표시",
    ["Shows an icon with cooldown spiral next to the arena frame when the opponent used their PvP trinket."] = "상대가 PvP 장신구를 사용하면 투기장 프레임 옆에 재사용 대기시간이 표시되는 아이콘을 띄웁니다.",
    ["Icon size"] = "아이콘 크기",
    ["Left of frame"] = "프레임 왼쪽",
    ["Right of frame"] = "프레임 오른쪽",
    ["Offset X"] = "X 오프셋",
    ["Offset Y"] = "Y 오프셋",
    ["Diminishing Returns Tracker"] = "효과 감소(DR) 추적기",
    ["Shows icons next to each arena frame for active DR categories (Stun, Fear, Polymorph etc.) with color indicator: |cff00ff00green|r = full, |cffffff00yellow|r = 1/2, |cffff8000orange|r = 1/4, |cffff0000red|r = immune."] = "각 투기장 프레임 옆에 적용 중인 효과 감소 항목(기절, 공포, 변이 등)을 아이콘으로 표시하며 색으로 단계를 알려줍니다: |cff00ff00초록|r = 전체, |cffffff00노랑|r = 1/2, |cffff8000주황|r = 1/4, |cffff0000빨강|r = 면역.",
    ["Enable DR tracking"] = "효과 감소 추적 사용",
    ["INTERRUPTED"] = "방해됨",
    ["Castbar for arena opponents"] = "투기장 상대 시전 바",
    ["Shows a castbar below the frame when the opponent casts or channels."] = "상대가 주문을 시전하거나 지속 시전할 때 프레임 아래에 시전 바를 표시합니다.",
    ["Collection of simple quality-of-life toggles: auto-accept (quest, res, summon), auto-sell, repair, hide UI spam, text sizes."] = "간단한 편의 기능 모음: 자동 수락(퀘스트, 부활, 소환), 자동 판매, 수리, UI 알림 숨기기, 글자 크기.",
    ["Auto-sold: %d items, +%s"] = "자동 판매: 아이템 %d개, +%s",
    ["Auto-sold: %d items."] = "자동 판매: 아이템 %d개.",
    ["Repair exceeds gold (%d < %d)."] = "수리 비용이 소지금을 초과합니다 (%d < %d).",
    ["Auto-repaired (%dg %ds)."] = "자동 수리 완료 (%d골드 %d실버).",
    ["MAX"] = "최대",
    ["General - Auto Actions"] = "일반 - 자동 동작",
    ["|cffaaaaaaSimple on/off switches for common QoL actions. Take effect immediately, no /reload needed.|r"] = "|cffaaaaaa자주 쓰는 편의 기능의 간단한 켜기/끄기 스위치입니다. 즉시 적용되며 /reload 가 필요 없습니다.|r",
    ["Auto-accept quests"] = "퀘스트 자동 수락",
    ["Automatically accepts quests when clicking an NPC."] = "NPC를 클릭하면 퀘스트를 자동으로 수락합니다.",
    ["Auto-turn in quests"] = "퀘스트 자동 완료",
    ["Automatically completes finished quests. Waits for user choice on multi-reward quests (no auto-pick)."] = "완료된 퀘스트를 자동으로 제출합니다. 보상이 여러 개인 퀘스트는 사용자가 선택할 때까지 기다립니다 (자동 선택 없음).",
    ["Auto-accept resurrect"] = "부활 자동 수락",
    ["Automatically clicks 'Accept' on resurrect popups (not in combat)."] = "부활 알림 창의 ‘수락’을 자동으로 클릭합니다 (전투 중 제외).",
    ["Auto-accept summon"] = "소환 자동 수락",
    ["Automatically clicks 'Accept' on warlock/stone summon popups."] = "흑마법사/소환석 소환 알림 창의 ‘수락’을 자동으로 클릭합니다.",
    ["Auto-release spirit in PvP/Arena"] = "PvP/투기장에서 자동 영혼 해방",
    ["Releases instantly on death in BG or arena."] = "전장이나 투기장에서 사망하면 즉시 영혼을 해방합니다.",
    ["Auto-sell junk (grey)"] = "잡템 자동 판매 (회색)",
    ["Sells all grey items when opening a vendor. Earnings shown in chat."] = "상인 창을 열면 모든 회색 아이템을 판매합니다. 수익은 대화창에 표시됩니다.",
    ["Auto-repair"] = "자동 수리",
    ["Repairs entire equipment at the vendor if gold is sufficient."] = "소지금이 충분하면 상인에게서 장비 전체를 수리합니다.",
    ["Stack-split popup: MAX button"] = "수량 분할 창: 최대 버튼",
    ["Adds a 'MAX' button to the quantity popup. Click = buy full stack (at vendor) or split completely (for bag items)."] = "수량 입력 창에 ‘최대’ 버튼을 추가합니다. 클릭 = 전체 묶음 구매(상인) 또는 전부 분할(가방 아이템).",
    ["Stack-split popup: VuloUI look"] = "수량 분할 창: VuloUI 외형",
    ["Restyles the quantity popup (stack buying/splitting) to match the addon look: dark panel, clean buttons and arrows. Turning this off needs a /reload."] = "수량 창(묶음 구매/분할)을 애드온 외형에 맞게 바꿉니다: 어두운 배경판, 깔끔한 버튼과 화살표. 끄려면 /reload 가 필요합니다.",
    ["Hide UI error messages"] = "UI 오류 메시지 숨기기",
    ["Hides the red error messages in the screen center."] = "화면 중앙의 빨간 오류 메시지를 숨깁니다.",
    ["Hide zone text"] = "지역 이름 숨기기",
    ["Hides the large zone name when entering new areas."] = "새 지역에 들어갈 때 나타나는 큰 지역 이름을 숨깁니다.",
    ["Hide level numbers on portrait"] = "초상화의 레벨 숫자 숨기기",
    ["Hides the level display on the Player/Target/Pet portrait."] = "플레이어/대상/소환수 초상화의 레벨 표시를 숨깁니다.",
    ["Hide keybind text on action buttons"] = "행동 단축 버튼의 단축키 글자 숨기기",
    ["Hides the small key labels (1, F1, etc.) on the action buttons."] = "행동 단축 버튼의 작은 키 표시(1, F1 등)를 숨깁니다.",
    ["Hide macro/spell names on action buttons"] = "행동 단축 버튼의 매크로/주문 이름 숨기기",
    ["Hides the text labels under the action buttons."] = "행동 단축 버튼 아래의 이름 표시를 숨깁니다.",
    ["Hide stack/charge numbers on action buttons"] = "행동 단축 버튼의 개수/충전 숫자 숨기기",
    ["Hides the small boxes with numbers at the top right (item stacks, charges, cooldown seconds for long CDs)."] = "오른쪽 위의 작은 숫자 상자를 숨깁니다 (아이템 개수, 충전 횟수, 긴 재사용 대기시간의 초 표시).",
    ["Hide raid group labels"] = "공격대 그룹 표시 숨기기",
    ["Hides the 'Group 1'/'Group 2' labels above the compact raid frames."] = "간략화된 공격대 프레임 위의 ‘그룹 1’/‘그룹 2’ 표시를 숨깁니다.",
    ["Mail Text Size"] = "우편 글자 크기",
    ["Font size in mail body (opened + sent mail)."] = "우편 본문의 글꼴 크기입니다 (받은 우편 + 보낸 우편).",
    ["Quest Text Size"] = "퀘스트 글자 크기",
    ["Font size in quest descriptions + quest log."] = "퀘스트 설명과 퀘스트 목록의 글꼴 크기입니다.",
    ["Book Text Size"] = "책 글자 크기",
    ["Font size in readable books and letters from item text."] = "읽을 수 있는 책과 아이템 문서의 글꼴 크기입니다.",
    ["Queue Timer"] = "대기열 시간 표시",
    ["Shows a countdown on the PvP/PvE queue pop dialog. Optional sound warning at 5 seconds."] = "PvP/PvE 대기열 알림 창에 남은 시간을 표시합니다. 5초 전 소리 경고를 켤 수 있습니다.",
    ["Queue expires in"] = "대기열 만료까지",
    ["|cff00c0ffQueueTimer:|r "] = "|cff00c0ffQueueTimer:|r ",
    ["Dungeon queue popped instantly!"] = "던전 대기열이 즉시 잡혔습니다!",
    ["Dungeon queue popped after %s"] = "던전 대기열이 %s 만에 잡혔습니다.",
    ["Dungeon queue popped."] = "던전 대기열이 잡혔습니다.",
    ["Queue popped instantly!"] = "대기열이 즉시 잡혔습니다!",
    ["Queue popped after %s"] = "대기열이 %s 만에 잡혔습니다.",
    ["Sound on queue pop"] = "대기열 알림 소리",
    ["Plays a sound as soon as the queue pops."] = "대기열이 잡히는 즉시 소리를 재생합니다.",
    ["5-second warning"] = "5초 경고",
    ["Plays 3 quick sounds when only 5 seconds remain to accept."] = "수락까지 5초 남으면 짧은 소리를 3번 재생합니다.",
    ["Hide other timers (e.g. BigWigs)"] = "다른 시간 표시 숨기기 (예: BigWigs)",
    ["Hides foreign StatusBars on the LFG ready popup so only our timer is visible."] = "LFG 수락 창의 외부 StatusBar를 숨겨 우리 시간 표시만 보이게 합니다.",
    ["Tooltip IDs"] = "툴팁 ID",
    ["Shows SpellID, ItemID, NPC ID and many other IDs in tooltips (based on idTip by silverwind)."] = "툴팁에 주문 ID, 아이템 ID, NPC ID 등 다양한 ID를 표시합니다 (silverwind의 idTip 기반).",
    ["|cff9b6cffTalents:|r "] = "|cff9b6cff특성:|r ",
    ["|cff9b6cffiLvL:|r %d"] = "|cff9b6cff아이템 레벨:|r %d",
    ["  |cff888888(off by default)|r"] = "  |cff888888(기본값: 꺼짐)|r",
    ["Shows %s in tooltips."] = "툴팁에 %s을(를) 표시합니다.",
    ["Shows additional ID lines in tooltips, e.g. spell, item or NPC IDs."] = "툴팁에 주문, 아이템, NPC ID 등 추가 ID 줄을 표시합니다.",
    ["Quick Select"] = "빠른 선택",
    ["All on"] = "모두 켜기",
    ["All off"] = "모두 끄기",
    ["Defaults"] = "기본값",
    ["Player Tooltip (Inspect-based)"] = "플레이어 툴팁 (살펴보기 기반)",
    ["|cffaaaaaaWhen you hover over a player, their average iLvL + talent distribution (e.g. 14/0/47) is shown in the tooltip. Data is cached 60s per player, inspect throttle 1/s.|r"] = "|cffaaaaaa플레이어에 마우스를 올리면 평균 아이템 레벨과 특성 분배(예: 14/0/47)가 툴팁에 표시됩니다. 자료는 플레이어당 60초 동안 저장되며, 살펴보기는 초당 1회로 제한됩니다.|r",
    ["Show average iLvL"] = "평균 아이템 레벨 표시",
    ["Show talent distribution (e.g. 14/0/47)"] = "특성 분배 표시 (예: 14/0/47)",
    ["ID Types"] = "ID 종류",
    ["Which IDs should be shown in tooltips? Some types are only active in Retail and are ignored in TBC (e.g. TraitNodeID, SourceID)."] = "툴팁에 어떤 ID를 표시할지 선택합니다. 일부 종류는 정식 서버에서만 작동하며 TBC에서는 무시됩니다 (예: TraitNodeID, SourceID).",
    ["Auto Item Buy"] = "아이템 자동 구매",
    ["Automatically buys configured items at configured vendors. Shift when opening the merchant window = emergency stop."] = "지정한 상인에게서 지정한 아이템을 자동으로 구매합니다. 상인 창을 열 때 Shift를 누르면 즉시 중단합니다.",
    ["|cffffd200[AutoItemBuy]|r "] = "|cffffd200[AutoItemBuy]|r ",
    ["Buying: "] = "구매 중: ",
    ["Close merchant window after purchase"] = "구매 후 상인 창 닫기",
    ["Closes the merchant window automatically ~0.2s after purchase."] = "구매 약 0.2초 후에 상인 창을 자동으로 닫습니다.",
    ["Chat message on each purchase"] = "구매할 때마다 대화창에 알림",
    ["|cffaaaaaaTip: Hold SHIFT when opening the merchant window to skip automatic purchase once.|r"] = "|cffaaaaaa팁: 상인 창을 열 때 SHIFT를 누르고 있으면 자동 구매를 한 번 건너뜁니다.|r",
    ["Add Vendor"] = "상인 추가",
    ["Vendor Name"] = "상인 이름",
    ["Add"] = "추가",
    ["|cffff5555Please enter a vendor name.|r"] = "|cffff5555상인 이름을 입력하세요.|r",
    ["|cffff5555Vendor '%s' already exists.|r"] = "|cffff5555상인 ‘%s’이(가) 이미 존재합니다.|r",
    ["Vendor '%s' added."] = "상인 ‘%s’이(가) 추가되었습니다.",
    ["Manage Vendors"] = "상인 관리",
    ["|cffaaaaaaNo vendors added yet. Add a vendor above, then select it here to configure items.|r"] = "|cffaaaaaa아직 추가된 상인이 없습니다. 위에서 상인을 추가한 뒤 여기에서 선택해 아이템을 설정하세요.|r",
    ["Currently selected vendor"] = "현재 선택된 상인",
    ["Delete this vendor"] = "이 상인 삭제",
    ["Vendor '%s' removed."] = "상인 ‘%s’이(가) 삭제되었습니다.",
    ["Items at '%s'"] = "‘%s’의 아이템",
    ["Item name (exactly as in-game)"] = "아이템 이름 (게임 내 표기 그대로)",
    ["|cffff5555Please enter an item name.|r"] = "|cffff5555아이템 이름을 입력하십시오.|r",
    ["Item '%s' added at vendor '%s'."] = "아이템 ‘%s’을(를) 상인 ‘%s’에 추가했습니다.",
    ["|cffaaaaaaItem names must match the in-game name exactly (including case and special characters).|r"] = "|cffaaaaaa아이템 이름은 게임 내 이름과 정확히 일치해야 합니다 (대소문자와 특수 문자 포함).|r",
    ["|cffaaaaaaNo items configured. Add items above that should be bought automatically at this vendor.|r"] = "|cffaaaaaa설정된 아이템이 없습니다. 이 상인에게서 자동으로 구매할 아이템을 위에 추가하십시오.|r",
    ["Remove"] = "제거",
    ["Item '%s' removed."] = "아이템 ‘%s’을(를) 제거했습니다.",
    ["Inspect Fix"] = "살펴보기 수정",
    ["Fixes stuck inspect bugs (no player inspect possible after a faulty close/timeout). Auto-reset after 8s + cleanup when InspectFrame closes + /inspectreset slash command."] = "살펴보기가 멈추는 오류를 수정합니다 (잘못된 종료나 시간 초과 후 다른 플레이어를 살펴볼 수 없는 현상). 8초 후 자동 초기화 + InspectFrame이 닫힐 때 정리 + /inspectreset 슬래시 명령어.",
    ["Fixes stuck inspect bugs (no player inspect possible after a faulty close/timeout). Auto-reset after a timeout + cleanup when InspectFrame closes + /inspectreset slash command."] = "살펴보기가 멈추는 오류를 수정합니다 (잘못된 종료나 시간 초과 후 다른 플레이어를 살펴볼 수 없는 현상). 시간 초과 후 자동 초기화 + InspectFrame이 닫힐 때 정리 + /inspectreset 슬래시 명령어.",
    ["Inspect state manually reset. Try again now."] = "살펴보기 상태를 수동으로 초기화했습니다. 이제 다시 시도하십시오.",
    ["|cffffff00[VuloClassicUI]|r Inspect state reset."] = "|cffffff00[VuloClassicUI]|r 살펴보기 상태를 초기화했습니다.",
    ["Auto-reset on timeout"] = "시간 초과 시 자동 초기화",
    ["If no response from the server comes after X seconds, the pending inspect state is automatically reset — so the next inspect attempt works again."] = "서버 응답이 X초 동안 오지 않으면 대기 중인 살펴보기 상태를 자동으로 초기화합니다. 따라서 다음 살펴보기 시도가 다시 정상적으로 작동합니다.",
    ["Aggressive reset before each inspect"] = "살펴볼 때마다 강제 초기화",
    ["Force-clears the inspect state before every NotifyInspect/InspectUnit call. Recommended for Anniversary because Blizzard's UI doesn't reliably clear the previous target's cache. Disable only if you have compatibility issues with another inspect addon."] = "모든 NotifyInspect/InspectUnit 호출 전에 살펴보기 상태를 강제로 비웁니다. Blizzard UI가 이전 대상의 캐시를 확실하게 비우지 않으므로 Anniversary에서는 사용을 권장합니다. 다른 살펴보기 애드온과 충돌이 있을 때만 끄십시오.",
    ["How long to wait for INSPECT_READY before auto-reset kicks in. 5 seconds is the new default for Anniversary — fast enough to recover quickly."] = "INSPECT_READY를 기다리는 시간이며, 이후 자동 초기화가 실행됩니다. Anniversary의 새 기본값은 5초로, 빠르게 복구할 수 있습니다.",
    ["NotifyInspect override: %s\nInspectUnit override:   %s\nInspectFrame hook:      %s"] = "NotifyInspect 대체: %s\\nInspectUnit 대체:   %s\\nInspectFrame 후크:      %s",
    ["|cffaaaaaaSlash commands: /inspectreset (force-reset), /inspectstate (debug info in chat)|r"] = "|cffaaaaaa슬래시 명령어: /inspectreset (강제 초기화), /inspectstate (대화창에 디버그 정보)|r",
    ["|cffaaaaaaWhat the fix does: replaces NotifyInspect and InspectUnit with wrappers that force-clear server state before each request. Plus full reset when the inspect frame closes or after a 5s timeout.|r"] = "|cffaaaaaa수정 내용: NotifyInspect와 InspectUnit을 요청 전에 서버 상태를 강제로 비우는 래퍼로 교체합니다. 또한 살펴보기 창이 닫히거나 5초가 지나면 전체를 초기화합니다.|r",
    ["Timeout (seconds)"] = "시간 초과 (초)",
    ["How long to wait for INSPECT_READY before auto-reset kicks in. 8 seconds is a good default — fast enough for out-of-range, slow enough not to abort normal server lag."] = "INSPECT_READY를 기다리는 시간이며, 이후 자동 초기화가 실행됩니다. 8초가 적당한 기본값으로, 사거리를 벗어난 경우에도 충분히 빠르고 일반적인 서버 지연을 중단시키지도 않습니다.",
    ["Manual Reset"] = "수동 초기화",
    ["Reset inspect state now"] = "살펴보기 상태 지금 초기화",
    ["Inspect state manually reset."] = "살펴보기 상태를 수동으로 초기화했습니다.",
    ["|cffaaaaaaSlash command: /inspectreset|r"] = "|cffaaaaaa슬래시 명령어: /inspectreset|r",
    ["NotifyInspect hook: %s\nInspectFrame hook: %s"] = "NotifyInspect 후크: %s\\nInspectFrame 후크: %s",
    ["|cff66ff66active|r"] = "|cff66ff66활성|r",
    ["|cffff8800waiting|r"] = "|cffff8800대기 중|r",
    ["|cffff8800waiting for Blizzard_InspectUI|r"] = "|cffff8800Blizzard_InspectUI 대기 중|r",
    ["|cffaaaaaaWhat the fix does: tracks active inspects with a timestamp, repaints late-arriving item data, re-requests an all-empty inspect once, and calls ClearInspectPlayer() on close + on timeout. Prevents a stuck state from blocking all subsequent inspects.|r"] = "|cffaaaaaa수정 내용: 진행 중인 살펴보기를 시각과 함께 추적하고, 늦게 도착한 아이템 정보를 다시 표시하며, 완전히 비어 있는 살펴보기를 한 번 재요청하고, 창이 닫힐 때와 시간 초과 시 ClearInspectPlayer()를 호출합니다. 상태가 멈춰 이후 모든 살펴보기가 막히는 것을 방지합니다.|r",
    ["Auto-retry empty inspects"] = "빈 살펴보기 자동 재시도",
    ["After the server answers, the item slots are repainted again shortly after (data often arrives late). If the window is still completely empty, the inspect is automatically requested one more time."] = "서버가 응답한 뒤 잠시 후 아이템 칸을 다시 표시합니다 (정보가 늦게 도착하는 경우가 많습니다). 창이 여전히 완전히 비어 있으면 살펴보기를 한 번 더 자동으로 요청합니다.",
    ["|cffaaaaaaStatus: %s|r"] = "|cffaaaaaa상태: %s|r",
    ["|cff66ff66Hook active|r"] = "|cff66ff66후크 활성|r",
    ["LFG Browse Nil Fix"] = "LFG 목록 Nil 오류 수정",
    ["Catches Lua errors in the Anniversary Group Finder (LFGBrowseSearchEntry_Update with stale resultIDs). Prevents chat spam and broken browse lists."] = "Anniversary 파티 찾기에서 발생하는 Lua 오류를 잡아냅니다 (오래된 resultID를 사용하는 LFGBrowseSearchEntry_Update). 대화창 도배와 목록 손상을 방지합니다.",
    ["|cffffff00[VuloClassicUI]|r Blizzard LFG browse error caught (stale entry skipped)."] = "|cffffff00[VuloClassicUI]|r Blizzard LFG 목록 오류를 처리했습니다 (오래된 항목 건너뜀).",
    ["Chat message on first error"] = "첫 오류 시 대화창 알림",
    ["Shows a brief message once per session in chat when an LFG browse error was caught."] = "LFG 목록 오류를 처리했을 때 세션당 한 번 대화창에 짧은 알림을 표시합니다.",
    ["This fix wraps Blizzard's |cffffffffLFGBrowseSearchEntry_Update|r function in a protected call (xpcall). When the entry crashes due to a stale resultID (\"searchResultInfo nil\"), the error is swallowed — Blizzard's next refresh automatically cleans up the list entry."] = "이 수정은 Blizzard의 |cffffffffLFGBrowseSearchEntry_Update|r 함수를 보호 호출(xpcall)로 감쌉니다. 오래된 resultID로 인해 항목이 오류를 일으키면 (‘searchResultInfo nil’) 오류를 무시하며, Blizzard의 다음 갱신이 자동으로 해당 목록 항목을 정리합니다.",
    ["waiting for Blizzard_GroupFinder_VanillaStyle"] = "Blizzard_GroupFinder_VanillaStyle 대기 중",
    ["Guild News Nil Fix"] = "길드 소식 Nil 오류 수정",
    ["Catches Lua errors in guild news entries (typically \"formatString\" or \"GuildUtil\") and replaces broken entries with a fallback text instead of letting the whole panel break."] = "길드 소식 항목의 Lua 오류(주로 ‘formatString’ 또는 ‘GuildUtil’)를 잡아내고, 패널 전체가 망가지는 대신 손상된 항목을 대체 문구로 바꿉니다.",
    ["|cffff8080Invalid guild news entry|r"] = "|cffff8080잘못된 길드 소식 항목|r",
    ["|cffffff00[VuloClassicUI]|r Blizzard guild news error caught (fallback applied)."] = "|cffffff00[VuloClassicUI]|r Blizzard 길드 소식 오류를 처리했습니다 (대체 문구 적용).",
    ["Shows a brief message once per session in chat when a guild news error was caught."] = "길드 소식 오류를 처리했을 때 세션당 한 번 대화창에 짧은 알림을 표시합니다.",
    ["This fix wraps Blizzard's |cffffffffGuildNewsButton_SetNews|r function in a protected call (xpcall). When an entry throws a known error (\"formatString\" or \"GuildUtil\"), the entry is replaced with a fallback text \"Invalid guild news entry\" — the panel remains usable."] = "이 수정은 Blizzard의 |cffffffffGuildNewsButton_SetNews|r 함수를 보호 호출(xpcall)로 감쌉니다. 항목이 알려진 오류(‘formatString’ 또는 ‘GuildUtil’)를 일으키면 해당 항목을 대체 문구 ‘잘못된 길드 소식 항목’으로 바꾸므로 패널을 계속 사용할 수 있습니다.",
    ["waiting for Blizzard_Communities"] = "Blizzard_Communities 대기 중",
    ["Auction Price Fix"] = "경매장 가격 오류 수정",
    ["Fixes a nil error in the German auction house UI (PriceDropdown not defined)."] = "독일어 경매장 UI의 nil 오류를 수정합니다 (PriceDropdown 미정의).",
    ["This fix addresses a known bug in the German WoW localization: the auction house UI references a \"PriceDropdown\" element that was never defined, which causes Lua errors when opening the auction house."] = "이 수정은 독일어 WoW 현지화의 알려진 오류를 해결합니다. 경매장 UI가 한 번도 정의된 적 없는 ‘PriceDropdown’ 요소를 참조하여 경매장을 열 때 Lua 오류가 발생합니다.",
    ["|cffaaaaaaCurrent locale: %s|r"] = "|cffaaaaaa현재 언어: %s|r",
    ["|cffaaaaaaThe fix only applies on German clients (deDE). On other languages the module is inactive.|r"] = "|cffaaaaaa이 수정은 독일어 클라이언트(deDE)에서만 적용됩니다. 다른 언어에서는 모듈이 비활성 상태입니다.|r",
    ["|cff66ff66applied|r"] = "|cff66ff66적용됨|r",
    ["skipped (deDE-only)"] = "건너뜀 (deDE 전용)",
    ["not applied"] = "적용 안 됨",
    ["Combat Text"] = "전투 문자",
    ["Custom floating combat text engine with configurable events, color, size and position."] = "표시할 사건, 색상, 크기, 위치를 설정할 수 있는 자체 전투 문자 엔진입니다.",
    ["Expressway (Default)"] = "Expressway (기본값)",
    ["Friz Quadrata (Blizzard)"] = "Friz Quadrata (Blizzard)",
    ["Arial Narrow"] = "Arial Narrow",
    ["Morpheus"] = "Morpheus",
    ["Skurri"] = "Skurri",
    ["LOW DURABILITY"] = "내구도 낮음",
    ["+Combat"] = "전투 시작",
    ["-Combat"] = "전투 종료",
    ["Interrupted: "] = "차단: ",
    ["Dispelled: "] = "해제: ",
    ["Purged: "] = "정화: ",
    ["Purged"] = "정화",
    ["Dispelled"] = "해제",
    ["dispelled"] = "해제됨",
    ["You gave"] = "내가 부여함",
    ["gave you"] = "나에게 부여함",
    ["reflected"] = "반사됨",
    ["Purged (enemy buff removed)"] = "정화 (적의 강화 효과 제거)",
    ["Dispelled (by you)"] = "해제 (내가 해제함)",
    ["Dispelled (your buff lost)"] = "해제 (내 강화 효과 상실)",
    ["Buff given"] = "강화 효과 부여",
    ["Buff received"] = "강화 효과 받음",
    ["Reflected"] = "반사",
    ["Show spell icons"] = "주문 아이콘 표시",
    ["Party member died"] = "파티원 사망",
    ["%s died"] = "%s 사망",
    ["Shows the spell icon inline next to the spell name."] = "주문 이름 옆에 주문 아이콘을 함께 표시합니다.",
    ["Parried"] = "무기 막기",
    ["Dodged"] = "회피",
    ["Missed"] = "빗나감",
    ["Blocked"] = "방패 막기",
    ["Absorbed"] = "흡수",
    ["|cffffffffCOMBAT TEXT|r"] = "|cffffffff전투 문자|r",
    ["Combat Text mover active. Drag or arrow keys (SHIFT=5px)."] = "전투 문자 이동 모드 활성화. 드래그 또는 방향키 (SHIFT=5px).",
    ["|cffaaaaaaCustom scrolling text engine above the player. Anniversary disabled Blizzard's old player FCT. Each event can have its own color + size + outline/shadow.|r"] = "|cffaaaaaa플레이어 위에 표시되는 자체 스크롤 문자 엔진입니다. Anniversary에서는 Blizzard의 기존 플레이어 전투 문자가 비활성화되었습니다. 각 사건마다 색상 + 크기 + 외곽선/그림자를 따로 지정할 수 있습니다.|r",
    ["Flashing combat notifications (with live preview) plus a scrolling combat-log text engine."] = "실시간 미리 보기가 있는 깜빡이는 전투 알림과 스크롤되는 전투 기록 문자 엔진입니다.",
    ["|cffaaaaaaNotifications (+/- Combat, Low Durability) flash centred and stack; combat-log events (interrupts, dispels, misses) scroll upward. Use Preview to position and style them.|r"] = "|cffaaaaaa알림(전투 시작/종료, 내구도 낮음)은 화면 중앙에서 깜빡이며 쌓이고, 전투 기록 사건(차단, 해제, 빗나감)은 위로 흘러갑니다. 미리 보기로 위치와 모양을 조정하십시오.|r",
    ["Show Preview"] = "미리 보기 표시",
    ["Shows all three notification messages on screen so you can position and style them. Turns off automatically when you close this window."] = "세 가지 알림 메시지를 모두 화면에 표시하여 위치와 모양을 조정할 수 있습니다. 이 창을 닫으면 자동으로 꺼집니다.",
    ["Notifications (flash & stack)"] = "알림 (깜빡임 및 누적)",
    ["Combat Log (scrolling)"] = "전투 기록 (스크롤)",
    ["Text"] = "문자",
    ["Outline Style"] = "외곽선 방식",
    ["Thick Outline"] = "두꺼운 외곽선",
    ["Flash Duration (sec.)"] = "깜빡임 지속시간 (초)",
    ["How long the +/- Combat flash stays before fading."] = "전투 시작/종료 깜빡임이 사라지기 전까지 유지되는 시간입니다.",
    ["Categories (Quick on/off)"] = "분류 (빠른 켜기/끄기)",
    ["Combat State (+/- Combat)"] = "전투 상태 (전투 시작/종료)",
    ["Combat start and combat end messages."] = "전투 시작 및 전투 종료 메시지입니다.",
    ["Combat Log Events"] = "전투 기록 사건",
    ["Interrupts, dispels, misses (Parry/Dodge/Block)."] = "차단, 해제, 빗나감 (무기 막기/회피/방패 막기).",
    ["Durability Warning"] = "내구도 경고",
    ["Low durability after combat exit."] = "전투 종료 후 내구도가 낮을 때 표시합니다.",
    ["Global Defaults"] = "전체 기본값",
    ["Per-Event Customization"] = "사건별 설정",
    ["Font for our combat text engine. Also used for Blizzard's mob FCT (DAMAGE_TEXT_FONT) when enabled below."] = "자체 전투 문자 엔진에 사용할 글꼴입니다. 아래에서 켜면 Blizzard의 몹 전투 문자(DAMAGE_TEXT_FONT)에도 적용됩니다.",
    ["Also apply font to Blizzard mob FCT"] = "Blizzard 몹 전투 문자에도 글꼴 적용",
    ["Additionally sets DAMAGE_TEXT_FONT globally - changes the font of the damage numbers above mobs/pets. Requires /reload to take effect."] = "DAMAGE_TEXT_FONT를 전역으로 설정하여 몹/소환수 위에 뜨는 피해량 숫자의 글꼴을 바꿉니다. 적용하려면 /reload가 필요합니다.",
    ["Default: Thick Outline"] = "기본값: 두꺼운 외곽선",
    ["Default: Shadow"] = "기본값: 그림자",
    ["Scroll Duration (sec.)"] = "스크롤 지속시간 (초)",
    ["Scroll Distance (px)"] = "스크롤 거리 (px)",
    ["Interrupted"] = "차단",
    ["Interrupted: Frostbolt"] = "차단: 얼음 화살",
    ["Dispelled/Purged"] = "해제/정화",
    ["Dispelled: Curse"] = "해제: 저주",
    ["Parried/Dodged/Missed"] = "무기 막기/회피/빗나감",
    ["Low Durability"] = "내구도 낮음",
    ["Durability Threshold (%)"] = "내구도 기준 (%)",
    ["Warning appears when at least one equipped item is below this value (after combat exit)."] = "전투 종료 후 착용 중인 장비가 하나라도 이 값 아래로 내려가면 경고가 표시됩니다.",
    ["Engine FCT (above mob/pet)"] = "엔진 전투 문자 (몹/소환수 위)",
    ["Sharper hit indicator font (Friz Quadrata)"] = "더 선명한 타격 표시 글꼴 (Friz Quadrata)",
    ["Engine FCT Scale"] = "엔진 전투 문자 크기",
    ["Damage numbers above mob/pet — bitmap scaling."] = "몹/소환수 위의 피해량 숫자 — 비트맵 크기 조절입니다.",
    ["Center"] = "중앙",
    ["Keeps the horizontal position and only centers vertically in the screen center."] = "가로 위치는 그대로 두고 화면 중앙을 기준으로 세로만 가운데 정렬합니다.",
    ["Unlock / Position"] = "잠금 해제 / 위치",
    ["Trinkets"] = "장신구",
    ["Two trinket slots on screen with cooldown display, dropdown selection and auto-queue."] = "재사용 대기시간 표시, 목록 선택, 자동 대기열을 갖춘 장신구 칸 두 개를 화면에 표시합니다.",
    ["|cffaaaaaaTwo trinket slots with cooldown, dropdown selection and auto-queue.|nLeft click = use, right click = dropdown.|r"] = "|cffaaaaaa재사용 대기시간, 목록 선택, 자동 대기열을 갖춘 장신구 칸 두 개입니다.|n좌클릭 = 사용, 우클릭 = 목록.|r",
    ["Show frame"] = "프레임 표시",
    ["Hides or shows the two trinket slots. Auto-queue continues to run while hidden."] = "두 장신구 칸을 숨기거나 표시합니다. 숨겨도 자동 대기열은 계속 작동합니다.",
    ["Position locked"] = "위치 잠금",
    ["If on, the frame cannot be accidentally moved."] = "켜면 프레임이 실수로 움직이지 않습니다.",
    ["Size"] = "크기",
    ["Scales the trinket slots."] = "장신구 칸의 크기를 조절합니다.",
    ["|cffaaaaaaTip: Left click on a slot uses the trinket, right click shows the selection list. Auto-queue is configured via right click -> Queue tab.|r"] = "|cffaaaaaa도움말: 칸을 좌클릭하면 장신구를 사용하고, 우클릭하면 선택 목록이 열립니다. 자동 대기열은 우클릭 → 대기열 탭에서 설정합니다.|r",
    ["Character Panel"] = "캐릭터 패널",
    ["Dark Skin"] = "다크 스킨",
    ["The dark look of the UI in one place: a built-in dark skin for action buttons and WeakAuras icons, plus an optional Dark Mode that darkens Blizzard's default frames, minimap and bars."] = "UI의 어두운 외형을 한곳에 모았습니다. 행동 단축바 버튼과 WeakAuras 아이콘용 내장 다크 스킨, 그리고 Blizzard 기본 프레임과 미니맵, 바를 어둡게 하는 선택형 다크 모드가 있습니다.",
    ["|cffaaaaaaThe dark look of the UI in one place: a built-in skin for action buttons and WeakAuras icons, plus an optional Dark Mode that re-tints Blizzard's default frames.|r"] = "|cffaaaaaaUI의 어두운 외형을 한곳에 모았습니다. 행동 단축바 버튼과 WeakAuras 아이콘용 내장 스킨, 그리고 Blizzard 기본 프레임의 색조를 바꾸는 선택형 다크 모드가 있습니다.|r",
    ["The dark action-bar button skin."] = "어두운 행동 단축바 버튼 스킨입니다.",
    ["Enable Dark Mode"] = "다크 모드 사용",
    ["Re-tints Blizzard's default frames, minimap and action-bar artwork to a dark tone. Off by default."] = "Blizzard 기본 프레임과 미니맵, 행동 단축바 이미지를 어두운 색조로 바꿉니다. 기본값은 꺼짐입니다.",
    ["|cffaaaaaaOptional: darkens and desaturates Blizzard's default artwork — unit frames, minimap and action bars — to a neutral dark tone. Reversible: turn it off and the gold look returns.|r"] = "|cffaaaaaa선택 사항: Blizzard 기본 이미지 — 유닛 프레임, 미니맵, 행동 단축바 — 를 어둡게 하고 채도를 낮춰 중립적인 어두운 색조로 만듭니다. 되돌릴 수 있으며, 끄면 금색 외형이 돌아옵니다.|r",
    ["Button Skin"] = "버튼 스킨",
    ["Built-in dark drop-shadow skin for action buttons and WeakAuras icons: black, rounded, soft rim. Several styles, no extra addons needed."] = "행동 단축바 버튼과 WeakAuras 아이콘을 위한 내장 어두운 그림자 스킨입니다. 검고 둥글며 부드러운 테두리를 가지고, 여러 방식이 있으며 추가 애드온이 필요 없습니다.",
    ["|cffaaaaaaBuilt-in dark drop-shadow skin. Action bars and WeakAuras icons are configured separately below.|r"] = "|cffaaaaaa내장 어두운 그림자 스킨입니다. 행동 단축바와 WeakAuras 아이콘은 아래에서 따로 설정합니다.|r",
    ["Action Bars"] = "행동 단축바",
    ["Skin the action bars"] = "행동 단축바에 스킨 적용",
    ["The dark action-bar border. Works on its own, and Dark Mode can drive it too."] = "어두운 행동 단축바 테두리입니다. 단독으로도 작동하며 다크 모드로도 켤 수 있습니다.",
    ["Bar style"] = "단축바 방식",
    ["Bar icon size"] = "단축바 아이콘 크기",
    ["How much of the button the icon fills in Shadow style. Higher = bigger icons with a thinner rim."] = "그림자 방식에서 아이콘이 버튼을 채우는 비율입니다. 값이 클수록 아이콘이 커지고 테두리가 얇아집니다.",
    ["WeakAuras Icons"] = "WeakAuras 아이콘",
    ["Skin WeakAuras icons"] = "WeakAuras 아이콘에 스킨 적용",
    ["WeakAuras style"] = "WeakAuras 방식",
    ["Style for WeakAuras icons, independent of the action bars."] = "행동 단축바와 별개로 적용되는 WeakAuras 아이콘 방식입니다.",
    ["Hide WeakAuras' own border"] = "WeakAuras 자체 테두리 숨기기",
    ["Hides the light border WeakAuras draws on icons, so only our dark rim shows. /reload to fully restore it."] = "WeakAuras가 아이콘에 그리는 밝은 테두리를 숨겨 우리 어두운 테두리만 보이게 합니다. 완전히 되돌리려면 /reload가 필요합니다.",
    ["Pick how the action buttons look. Rounded/Circle use an icon mask; Minimal is just the cropped icon."] = "행동 단축바 버튼의 모양을 선택합니다. 둥근 아이콘/원형은 아이콘 마스크를 사용하고, 최소는 잘라낸 아이콘만 표시합니다.",
    ["Shadow (dark rounded rim)"] = "그림자 (어두운 둥근 테두리)",
    ["Rounded icon (masked corners)"] = "둥근 아이콘 (모서리 마스크)",
    ["Square (black edge)"] = "사각형 (검은 테두리)",
    ["Square (accent edge)"] = "사각형 (강조 테두리)",
    ["Circle"] = "원형",
    ["Minimal (icon only)"] = "최소 (아이콘만)",
    ["Minimal Dark (darkened Blizzard border)"] = "최소 다크 (어둡게 한 Blizzard 테두리)",
    ["|cffaaaaaaNote: turning a skin off fully reverts after a /reload.|r"] = "|cffaaaaaa참고: 스킨을 끄면 /reload 후 완전히 되돌아갑니다.|r",
    ["Also skin pet & stance buttons"] = "소환수 및 태세 버튼에도 스킨 적용",
    ["Enhances the character panel: iLvL per slot, socket display, shortened enchant text."] = "캐릭터 패널을 개선합니다: 칸별 아이템 레벨, 홈 표시, 축약된 마법부여 문구.",
    ["Show item level per slot"] = "칸별 아이템 레벨 표시",
    ["Show average item level"] = "평균 아이템 레벨 표시",
    ["Show sockets"] = "홈 표시",
    ["Shorten enchant text (DE/EN)"] = "마법부여 문구 축약 (DE/EN)",
    ["Example: 'Stamina' -> 'Stam', 'Ausdauer' -> 'Ausd'."] = "예: ‘Stamina’ → ‘Stam’, ‘Ausdauer’ → ‘Ausd’.",
    ["Treat rings as enchantable"] = "반지도 마법부여 가능으로 처리",
    ["Also shows enchant text on rings (TBC: some professions can enchant rings). /reload required."] = "반지에도 마법부여 문구를 표시합니다 (TBC: 일부 전문 기술은 반지에 마법부여할 수 있습니다). /reload가 필요합니다.",
    ["Text Size"] = "문자 크기",
    ["Item Level Text Size"] = "아이템 레벨 문자 크기",
    ["Font size of the item level number on each item slot. Takes effect immediately when the character panel is open."] = "각 장비 칸에 표시되는 아이템 레벨 숫자의 글꼴 크기입니다. 캐릭터 패널이 열려 있으면 즉시 적용됩니다.",
    ["Note: Some changes only take full effect after /reload, since the character panel is hooked on load."] = "참고: 캐릭터 패널은 불러올 때 후크되므로 일부 변경 사항은 /reload 후에야 완전히 적용됩니다.",
    ["|cffff0000No Ench|r"] = "|cffff0000마법부여 없음|r",
    ["|c%siLvL - %d|r"] = "|c%s아이템 레벨 - %d|r",
    ["Gold Tracker"] = "골드 추적기",
    ["Shows in the backpack gold tooltip how much gold has been gained or spent since the last reset. Per-char persistent."] = "마지막 초기화 이후 얻거나 쓴 골드를 가방 골드 툴팁에 표시합니다. 캐릭터별로 저장됩니다.",
    ["Gold Tracker reset|r. Start = "] = "골드 추적기 초기화|r. 시작 = ",
    ["Gold Balance|r"] = "골드 수지|r",
    ["Gained:|r"] = "획득:|r",
    ["Spent:|r"] = "지출:|r",
    ["|cffffffffNet:|r"] = "|cffffffff합계:|r",
    ["Start:|r"] = "시작:|r",
    ["Now:|r"] = "현재:|r",
    ["Reset with /vcui goldreset|r"] = "/vcui goldreset 명령어로 초기화|r",
    ["|cffaaaaaaShows in the backpack gold tooltip the balance since the last manual reset:|n  - |cff44ff44Gained|r (quests, loot, vendor sales, mail)|n  - |cffff4444Spent|r (repair, vendor buy, mail cost)|n  - |cffffffffNet|r (+/- since reset)|n|nValues are |cffffffffper-char persistent|r across /reload and logout.|nOffline gold (AH mail, trade) is not counted.|n|nReset: button below or |cffffff00/vcui goldreset|r.|r"] = "|cffaaaaaa마지막 수동 초기화 이후의 수지를 가방 골드 툴팁에 표시합니다:|n  - |cff44ff44획득|r (퀘스트, 전리품, 상인 판매, 우편)|n  - |cffff4444지출|r (수리, 상인 구매, 우편 요금)|n  - |cffffffff합계|r (초기화 이후 +/-)|n|n수치는 /reload와 접속 종료 후에도 |cffffffff캐릭터별로 저장|r됩니다.|n오프라인 골드(경매장 우편, 거래)는 계산되지 않습니다.|n|n초기화: 아래 버튼 또는 |cffffff00/vcui goldreset|r.|r",
    ["Reset session"] = "세션 초기화",
    ["Class Specific"] = "직업별 기능",
    ["|cffaaaaaaVampiric Touch mana tracker — shows live how much mana you've given to the group (5% of shadow damage per tick, per mana user).|n|cffffffffReset automatically on combat start.|r|r"] = "|cffaaaaaa흡혈의 손길 마나 추적기 — 파티에 공급한 마나를 실시간으로 표시합니다 (지속 피해 틱마다 암흑 피해의 5%, 마나 사용자별).|n|cffffffff전투 시작 시 자동으로 초기화됩니다.|r|r",
    ["|cffff8800These tools are only active while playing a Priest.|r"] = "|cffff8800이 도구는 사제로 플레이할 때만 활성화됩니다.|r",
    ["No tools yet"] = "아직 도구 없음",
    ["|cffaaaaaaNo class-specific tools for this class yet. Got an idea? Let me know!|r"] = "|cffaaaaaa이 직업을 위한 전용 도구가 아직 없습니다. 좋은 생각이 있다면 알려 주십시오!|r",
    ["|cff9b6cffVT Mana:|r %d"] = "|cff9b6cffVT 마나:|r %d",
    ["|cff9b6cffVT Mana:|r 0"] = "|cff9b6cffVT 마나:|r 0",
    ["Vampiric Touch: %d mana given to the group."] = "흡혈의 손길: 파티에 마나 %d을(를) 공급했습니다.",
    ["|cffffffffVT MANA|r"] = "|cffffffffVT 마나|r",
    ["VT mana frame: x=%.0f, y=%.0f"] = "VT 마나 프레임: x=%.0f, y=%.0f",
    ["VT mana mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "VT 마나 이동 모드 활성화. |cff9b6cff드래그|r 또는 |cff9b6cff방향키|r (SHIFT = 5px).",
    ["VT mana mover disabled."] = "VT 마나 이동 모드 비활성화.",
    ["Print to chat at combat end"] = "전투 종료 시 대화창에 출력",
    ["Writes a summary in chat after each fight."] = "전투가 끝날 때마다 대화창에 요약을 표시합니다.",
    ["Reset manually"] = "수동 초기화",
    ["VT mana reset."] = "VT 마나를 초기화했습니다.",
    ["Shadow DoT Tracker"] = "암흑 DoT 추적기",
    ["|cffaaaaaaTracks your Shadow DoTs on the target. |cff44ff44Green|r = a buff is up that makes it hit harder if you recast now (TBC snapshot); |cffff4444red|r = about to expire.|r"] = "|cffaaaaaa대상에게 걸린 내 암흑 DoT를 추적합니다. |cff44ff44초록색|r = 지금 다시 시전하면 더 강하게 들어가는 강화 효과가 켜져 있음 (TBC 스냅샷), |cffff4444빨간색|r = 곧 만료됨.|r",
    ["Bars"] = "바",
    ["Icons"] = "아이콘",
    ["Shadow Word: Pain"] = "어둠의 권능: 고통",
    ["Vampiric Touch"] = "흡혈의 손길",
