    ["Spacing"] = "간격",
    ["Color the timer text"] = "시간 문자에 색상 적용",
    ["Show recast gain %"] = "재시전 이득 % 표시",
    ["Shows how much harder a fresh cast would hit right now (e.g. +12% with a spell power proc up). Negative values mean the running DoT snapshotted stronger — keep it."] = "지금 새로 시전하면 얼마나 더 강하게 들어가는지 표시합니다 (예: 주문력 발동이 켜져 있으면 +12%). 음수 값은 진행 중인 DoT가 더 강하게 스냅샷되었다는 뜻이므로 그대로 두십시오.",
    ["DoT Tracker"] = "DoT 추적기",
    ["|cffaaaaaaTracks your DoTs on the target. |cff44ff44Green|r = a buff is up that makes it hit harder if you recast now (TBC snapshot); |cffff4444red|r = about to expire.|r"] = "|cffaaaaaa대상에게 걸린 내 DoT를 추적합니다. |cff44ff44초록색|r = 지금 다시 시전하면 더 강하게 들어가는 강화 효과가 켜져 있음 (TBC 스냅샷), |cffff4444빨간색|r = 곧 만료됨.|r",
    ["|cffff8800Only active while playing a %s.|r"] = "|cffff8800%s(으)로 플레이할 때만 활성화됩니다.|r",
    ["|cffaaaaaaTracks your Warlock DoTs (Corruption, Curse of Agony, Unstable Affliction, Siphon Life, Immolate, Curse of Doom) on the target, with the same recast-snapshot readout as the Priest tracker.|r"] = "|cffaaaaaa대상에게 걸린 흑마법사 DoT(부패, 고통의 저주, 불안정한 고통, 생명력 흡수, 제물, 파멸의 저주)를 추적하며, 사제 추적기와 동일한 재시전 스냅샷 정보를 표시합니다.|r",
    ["Corruption"] = "부패",
    ["Curse of Agony"] = "고통의 저주",
    ["Unstable Affliction"] = "불안정한 고통",
    ["Siphon Life"] = "생명력 흡수",
    ["Immolate"] = "제물",
    ["Curse of Doom"] = "파멸의 저주",
    ["|cffffffffSHADOW DOTS|r"] = "|cffffffff암흑 DOT|r",
    ["|cffffffffDOTS|r"] = "|cffffffffDOT|r",
    ["Shadow DoTs: x=%.0f, y=%.0f"] = "암흑 DoT: x=%.0f, y=%.0f",
    ["Shadow DoTs mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "암흑 DoT 이동 모드 활성화. |cff9b6cff드래그|r 또는 |cff9b6cff방향키|r (SHIFT = 5px).",
    ["Shadow DoTs mover disabled."] = "암흑 DoT 이동 모드 비활성화.",
    ["Mark empty sockets"] = "빈 홈 표시",
    ["Adds a red ring around item sockets that have no gem."] = "보석이 없는 아이템 홈 주위에 빨간 테두리를 추가합니다.",
    ["Text shadow (instead of outline)"] = "문자 그림자 (외곽선 대신)",
    ["Cleaner text with a drop shadow instead of a thick outline."] = "두꺼운 외곽선 대신 그림자를 사용해 더 깔끔한 문자를 표시합니다.",
    ["|cffaaaaaaA modern round minimap with a beveled ring, zone text and clock in a slim pill. Zoom with the mouse wheel. |cffffffffShift+drag the map|r to move it — or use Unlock / the addon's own Edit Mode (/vedit). Blizzard's Edit Mode does not manage this map.|r"] = "|cffaaaaaa경사진 테두리와 지역 이름, 시계를 얇은 띠에 담은 현대적인 원형 미니맵입니다. 마우스 휠로 확대/축소합니다. |cffffffffShift+드래그|r로 지도를 옮기거나 잠금 해제 또는 애드온 자체 편집 모드(/vedit)를 사용하십시오. Blizzard의 편집 모드는 이 지도를 관리하지 않습니다.|r",
    ["|cffffffffMINIMAP|r"] = "|cffffffff미니맵|r",
    ["Minimap: x=%.0f, y=%.0f"] = "미니맵: x=%.0f, y=%.0f",
    ["Minimap mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "미니맵 이동 모드 활성화. |cff9b6cff드래그|r 또는 |cff9b6cff방향키|r (SHIFT = 5px).",
    ["Minimap module disabled — /reload restores the default layout completely."] = "미니맵 모듈이 비활성화되었습니다 — /reload하면 기본 배치가 완전히 복원됩니다.",
    ["Minimap ping: %s"] = "미니맵 신호: %s",
    ["Shape"] = "모양",
    ["Round"] = "원형",
    ["Accent ring"] = "강조 테두리",
    ["Ring color"] = "테두리 색상",
    ["Accent (purple)"] = "강조 (보라색)",
    ["Class color"] = "직업 색상",
    ["Custom color"] = "사용자 지정 색상",
    ["Theme color"] = "테마 색상",
    ["Dark guild & communities window"] = "어두운 길드 및 커뮤니티 창",
    ["Restyles the guild and communities window to the same dark look. Turning it off needs a /reload."] = "길드 및 커뮤니티 창을 같은 어두운 외형으로 바꿉니다. 끄려면 /reload가 필요합니다.",
    ["Debuffs on target (yours only)"] = "대상의 약화 효과 (내 것만)",
    ["Missing buffs (reminder)"] = "없는 강화 효과 (알림)",
    ["|cffaaaaaaIcons appear while YOUR debuff/DoT is on the target, with its remaining time. Add the debuff by name or ID.|r"] = "|cffaaaaaa내 약화 효과나 DoT가 대상에게 걸려 있는 동안 남은 시간과 함께 아이콘이 표시됩니다. 약화 효과를 이름이나 ID로 추가하십시오.|r",
    ["|cffaaaaaaIcons appear while the buff is MISSING on you - a reminder for weapon oils, blessings, food buffs. Add the buff by name or ID.|r"] = "|cffaaaaaa내게 강화 효과가 없을 때 아이콘이 표시됩니다. 무기 오일, 축복, 음식 강화 효과를 잊지 않도록 알려 줍니다. 강화 효과를 이름이나 ID로 추가하십시오.|r",
    ["Tint blue when out of mana"] = "마나가 부족하면 파란색으로 표시",
    ["Tint red when out of range"] = "사거리 밖이면 빨간색으로 표시",
    ["Needs a target; uses the spell's own range."] = "대상이 필요하며, 해당 주문의 사거리를 사용합니다.",
    ["Auto-track equipped trinkets"] = "착용한 장신구 자동 추적",
    ["Keeps both equipped trinkets in this group automatically - they follow along when you swap trinkets."] = "착용한 두 장신구를 이 그룹에 자동으로 유지합니다. 장신구를 교체하면 함께 바뀝니다.",
    ["Duplicate"] = "복제",
    ["Copies the selected group with all entries and layout settings."] = "선택한 그룹을 모든 항목과 배치 설정까지 복사합니다.",
    ["(copy)"] = "(사본)",
    ["Show tooltips on hover"] = "마우스를 올리면 툴팁 표시",
    ["The icons then intercept the mouse - leave this off if the bar sits over clickable UI."] = "그러면 아이콘이 마우스 입력을 가로챕니다. 바가 클릭 가능한 UI 위에 있다면 꺼 두십시오.",
    ["Copy the link with Ctrl+C:"] = "Ctrl+C로 링크 복사:",
    ["Click: copy link"] = "클릭: 링크 복사",
    ["|cffaaaaaaColors everything that is purple today in the color of your choice - sidebar, borders, highlights, bars. A /reload applies it everywhere.|r"] = "|cffaaaaaa현재 보라색으로 표시되는 모든 요소를 원하는 색상으로 바꿉니다 — 측면 막대, 테두리, 강조, 바. /reload하면 모든 곳에 적용됩니다.|r",
    ["Preset"] = "사전 설정",
    ["Purple (default)"] = "보라색 (기본값)",
    ["Turquoise"] = "청록색",
    ["Pink"] = "분홍색",
    ["Orange"] = "주황색",
    ["Theme color changed. /reload applies it to everything (elements already drawn keep the old color until then)."] = "테마 색상을 변경했습니다. /reload하면 모든 곳에 적용됩니다 (이미 그려진 요소는 그때까지 이전 색상을 유지합니다).",
    ["Custom ring color"] = "사용자 지정 테두리 색상",
    ["A thin colored line around the dark ring (round shape only)."] = "어두운 테두리 주위의 얇은 색상 선입니다 (원형 모양에서만).",
    ["Zone panel"] = "지역 패널",
    ["Zone text and clock"] = "지역 이름과 시계",
    ["Above the map"] = "지도 위",
    ["Below the map"] = "지도 아래",
    ["Hidden"] = "숨김",
    ["Show clock"] = "시계 표시",
    ["Show date"] = "날짜 표시",
    ["Shows the date next to the clock. Click it to open the calendar."] = "시계 옆에 날짜를 표시합니다. 클릭하면 달력이 열립니다.",
    ["Buttons"] = "버튼",
    ["Zoom buttons (+/-)"] = "확대/축소 버튼 (+/-)",
    ["Shows a flat + and - on the right edge of the map. The mouse wheel always zooms too."] = "지도 오른쪽 가장자리에 납작한 + 와 - 를 표시합니다. 마우스 휠로도 항상 확대/축소할 수 있습니다.",
    ["Show day/night button"] = "낮/밤 버튼 표시",
    ["Restyle addon buttons"] = "애드온 버튼 모양 변경",
    ["Removes the gold borders from other addons' minimap buttons and gives them a clean round look. Turning this off needs a /reload."] = "다른 애드온의 미니맵 버튼에서 금색 테두리를 없애고 깔끔한 원형 모양으로 만듭니다. 끄려면 /reload가 필요합니다.",
    ["Addon buttons only on mouseover"] = "마우스를 올릴 때만 애드온 버튼 표시",
    ["Hides other addons' minimap buttons until the mouse is over the minimap."] = "마우스를 미니맵 위에 올릴 때까지 다른 애드온의 미니맵 버튼을 숨깁니다.",
    ["Ping in chat"] = "대화창에 신호 표시",
    ["Prints who pinged the minimap."] = "미니맵에 신호를 보낸 사람을 표시합니다.",
    ["Totem Bar"] = "토템 바",
    ["|cffaaaaaa|cffffffffLeft-click|r an icon to (re)cast that element's totem, |cffffffffhover|r a slot to pick which totem from the icon list, |cffffffffmiddle-click|r to recall all totems. The icon border turns red just before the totem expires.|r"] = "|cffaaaaaa아이콘을 |cffffffff좌클릭|r하면 해당 속성의 토템을 (다시) 소환하고, 칸에 |cffffffff마우스를 올리면|r 아이콘 목록에서 토템을 고를 수 있으며, |cffffffff휠클릭|r하면 모든 토템을 회수합니다. 토템이 사라지기 직전에 아이콘 테두리가 빨간색으로 바뀝니다.|r",
    ["|cffff8800Only active while playing a Shaman.|r"] = "|cffff8800주술사로 플레이할 때만 활성화됩니다.|r",
    ["Totem set"] = "토템 세트",
    ["Active set"] = "활성 세트",
    ["Set name"] = "세트 이름",
    ["New set"] = "새 세트",
    ["Delete set"] = "세트 삭제",
    ["(auto: last cast)"] = "(자동: 마지막 소환)",
    ["|cff888888(cast a totem to add it here)|r"] = "|cff888888(토템을 소환하면 여기에 추가됩니다)|r",
    ["Shown elements"] = "표시할 속성",
    ["Sound before a totem expires"] = "토템 만료 전 소리 재생",
    ["Icon border (action-bar style)"] = "아이콘 테두리 (행동 단축바 방식)",
    ["Style"] = "방식",
    ["VuloUI (dark)"] = "VuloUI (어두움)",
    ["Classic (metal)"] = "Classic (금속)",
    ["Flyout direction"] = "확장 메뉴 방향",
    ["Which way the totem picker opens when you hover a slot. Automatic picks the side away from the screen edge."] = "칸에 마우스를 올렸을 때 토템 선택기가 열리는 방향입니다. 자동은 화면 가장자리 반대쪽을 선택합니다.",
    ["Automatic"] = "자동",
    ["Upwards"] = "위쪽",
    ["Downwards"] = "아래쪽",
    ["To the left"] = "왼쪽",
    ["To the right"] = "오른쪽",
    ["Open flyout in combat"] = "전투 중 확장 메뉴 열기",
    ["Tooltip with cooldown on hover"] = "마우스를 올리면 재사용 대기시간 툴팁 표시",
    ["Hovering a totem slot or a picker icon shows the totem name and its remaining cooldown."] = "토템 칸이나 선택기 아이콘에 마우스를 올리면 토템 이름과 남은 재사용 대기시간을 표시합니다.",
    ["Off = hovering a slot never opens the totem picker while you are fighting (clicks still cast). The picker now also closes itself on mouse-out and after every cast, even in combat."] = "끄면 전투 중에 칸에 마우스를 올려도 토템 선택기가 열리지 않습니다 (클릭 소환은 계속 작동합니다). 선택기는 이제 마우스가 벗어날 때와 소환할 때마다 전투 중에도 스스로 닫힙니다.",
    ["Earth"] = "대지",
    ["Water"] = "물",
    ["|cffffffffTOTEMS|r"] = "|cffffffff토템|r",
    ["Totems: x=%.0f, y=%.0f"] = "토템: x=%.0f, y=%.0f",
    ["Totem timer mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "토템 타이머 이동 모드 활성화. |cff9b6cff드래그|r 또는 |cff9b6cff방향키|r (SHIFT = 5px).",
    ["Totem timer mover disabled."] = "토템 타이머 이동 모드 비활성화.",
    ["|cffff5555Class tool error:|r %s"] = "|cffff5555직업 도구 오류:|r %s",
    ["EDIT MODE"] = "편집 모드",
    ["Edit Mode"] = "편집 모드",
    ["Open Edit Mode"] = "편집 모드 열기",
    ["Close Edit Mode and lock all windows. Your changes stay applied."] = "편집 모드를 닫고 모든 창을 잠급니다. 변경 사항은 그대로 적용됩니다.",
    ["Keep the current arrangement and carry on editing. Discard then returns to this point instead of to how things looked when Edit Mode opened."] = "현재 배치를 유지하고 계속 편집합니다. 이후 되돌리기는 편집 모드를 열었을 때가 아니라 이 시점으로 돌아갑니다.",
    ["Window positions saved."] = "창 위치를 저장했습니다.",
    ["Exit"] = "종료",
    ["Close"] = "닫기",
    ["Reset"] = "초기화",
    ["Reset this frame"] = "이 프레임 초기화",
    ["Reset all VuloUI window positions to the screen centre."] = "모든 VuloUI 창 위치를 화면 중앙으로 초기화합니다.",
    ["Reset all VuloUI window positions to the screen centre?"] = "모든 VuloUI 창 위치를 화면 중앙으로 초기화할까요?",
    ["Done — lock everything"] = "완료 — 전체 잠금",
    ["Grid"] = "격자",
    ["Snap"] = "격자 맞춤",
    ["Show an alignment grid."] = "정렬용 격자를 표시합니다.",
    ["Snap windows to the grid while dragging."] = "드래그하는 동안 창을 격자에 맞춥니다.",
    ["%d frames here - hold Alt to cycle"] = "여기에 프레임 %d개 - Alt를 누르면 차례로 선택",
    ["Drag a box, or hover it and use the arrow keys (Shift = 5px). Shift+click to select several and drag them together."] = "상자를 드래그하거나, 마우스를 올린 뒤 방향키를 사용하십시오 (Shift = 5px). Shift+클릭으로 여러 개를 선택해 함께 옮길 수 있습니다.",
    ["Which screen point the frame is pinned to (keeps it put across resolution changes)."] = "프레임이 고정되는 화면 지점입니다 (해상도가 바뀌어도 위치가 유지됩니다).",
    ["ANCHOR"] = "고정점",
    ["POSITION"] = "위치",
    ["SCALE"] = "크기",
    ["FREE MOVE"] = "자유 이동",
    ["FOLLOW WINDOW"] = "창 따라가기",
    ["Pins this window to another one - it then moves along whenever that window is moved. Dragging this window keeps the pin and just updates the distance."] = "이 창을 다른 창에 고정합니다. 그러면 그 창이 움직일 때마다 함께 움직입니다. 이 창을 드래그해도 고정은 유지되고 간격만 갱신됩니다.",
    ["Not possible - that would create a loop."] = "불가능합니다 - 순환이 발생합니다.",
    ["Anchor to window..."] = "창에 고정...",
    ["WIDTH LIKE"] = "너비 일치",
    ["HEIGHT LIKE"] = "높이 일치",
    ["Takes its width from another window and keeps it."] = "다른 창의 너비를 가져와 계속 유지합니다.",
    ["Takes its height from another window and keeps it."] = "다른 창의 높이를 가져와 계속 유지합니다.",
    ["This window sets its own size - the match will not stick."] = "이 창은 크기를 스스로 정하므로 일치 설정이 유지되지 않습니다.",
    ["Drag a box, or hover it and use the arrow keys (Shift = 5px). Hold Shift while dragging to lock one axis. Shift+right-click hides a box that is in the way."] = "상자를 끌거나, 마우스를 올린 뒤 방향키를 사용하세요 (Shift = 5px). 끄는 동안 Shift를 누르면 한 축으로 고정됩니다. Shift+오른쪽 클릭하면 방해되는 상자를 숨깁니다.",
    ["Then click any window to anchor this one to it."] = "그런 다음 아무 창이나 클릭하면 이 창이 그 창에 고정됩니다.",
    ["Click a window to anchor it (right-click to cancel)."] = "고정할 창을 클릭하세요 (오른쪽 클릭하면 취소).",
    ["ANCHOR SIDE"] = "고정 방향",
    ["Centered"] = "가운데",
    ["Top of"] = "위쪽",
    ["Bottom of"] = "아래쪽",
    ["Discard"] = "버리기",
    ["Discard changes and revert every window to how it was when Edit Mode opened."] = "변경 사항을 버리고 모든 창을 편집 모드를 연 시점의 상태로 되돌립니다.",
    ["Discard all changes made since opening Edit Mode?"] = "편집 모드를 연 뒤의 모든 변경 사항을 버릴까요?",
    ["Pin this frame to a screen edge/corner so it stays put across resolution changes. Off keeps it centred."] = "이 프레임을 화면 가장자리나 모서리에 붙여 해상도가 바뀌어도 위치를 유지합니다. 끄면 화면 중앙 기준으로 유지합니다.",
    ["Leave this window unlocked so you can still drag it after closing Edit Mode. Stays unlocked through /reload."] = "편집 모드를 닫은 뒤에도 끌어 옮길 수 있도록 이 창의 잠금을 해제한 채로 둡니다. /reload 후에도 해제 상태가 유지됩니다.",
    ["LAYOUTS"] = "배치",
    ["Layouts"] = "배치",
    ["SAVED"] = "저장됨",
    ["No layouts saved"] = "저장된 배치 없음",
    ["No layout selected."] = "선택된 배치가 없습니다.",
    ["Save, load, export and import named window layouts."] = "이름을 지정한 창 배치를 저장, 불러오기, 내보내기, 가져오기 합니다.",
    ["Save your window arrangement, then load or share it any time."] = "창 배열을 저장한 뒤 언제든 불러오거나 공유하세요.",
    ["Pick a saved layout to load, delete or export."] = "불러오거나 삭제, 내보낼 저장된 배치를 선택하세요.",
    ["Save current as..."] = "현재 상태를 다른 이름으로 저장...",
    ["Name for this layout:"] = "이 배치의 이름:",
    ["Delete layout '%s'?"] = "배치 ‘%s’을(를) 삭제할까요?",
    ["Layout '%s' saved."] = "배치 ‘%s’을(를) 저장했습니다.",
    ["Applied layout '%s' (%d frames)."] = "배치 ‘%s’을(를) 적용했습니다 (프레임 %d개).",
    ["Layout '%s' imported."] = "배치 ‘%s’을(를) 가져왔습니다.",
    ["Import"] = "가져오기",
    ["Export"] = "내보내기",
    ["Imported"] = "가져옴",
    ["Import failed (%s)."] = "가져오기 실패 (%s).",
    ["Paste a layout string and confirm:"] = "배치 문자열을 붙여넣고 확인하세요:",
    ["Copy this string (Ctrl+A, Ctrl+C):"] = "이 문자열을 복사하세요 (Ctrl+A, Ctrl+C):",
    ["click to edit"] = "클릭하여 편집",
    ["Move it in the unified Edit Mode (/vedit)."] = "통합 편집 모드(/vedit)에서 옮기세요.",
    ["Drag the combat-text box in the unified Edit Mode (/vedit)."] = "통합 편집 모드(/vedit)에서 전투 문자 상자를 끌어 옮기세요.",
    ["|cffffffffARENA FRAMES|r"] = "|cffffffff투기장 프레임|r",
    ["|cff44ff44Edit Mode is ON.|r Close this window to reach the boxes."] = "|cff44ff44편집 모드가 켜졌습니다.|r 상자를 조작하려면 이 창을 닫으세요.",
    ["|cffaaaaaaMove everything in one editor: VuloUI windows and Blizzard's frames (player, target, focus, minimap, buffs). They snap to a shared grid.|r"] = "|cffaaaaaa하나의 편집기에서 모두 옮기세요: VuloUI 창과 Blizzard 프레임(플레이어, 대상, 주시 대상, 미니맵, 강화 효과). 공용 격자에 맞춰 정렬됩니다.|r",
    ["|cff888888• Drag a purple box to move that frame.|n• Hover a box, then arrow keys fine-tune (SHIFT = 5px).|n• Right-click a box for exact X / Y.|n• |cffffffff/vedit|r toggles Edit Mode too.|r"] = "|cff888888• 보라색 상자를 끌면 해당 프레임이 이동합니다.|n• 상자에 마우스를 올린 뒤 방향키로 미세 조정합니다 (SHIFT = 5px).|n• 상자를 오른쪽 클릭하면 정확한 X / Y를 입력합니다.|n• |cffffffff/vedit|r로도 편집 모드를 전환합니다.|r",
    ["Enable 'Target and Focus' in Blizzard's Edit Mode settings, then /reload, so VuloUI can move the target/focus frame."] = "Blizzard 편집 모드 설정에서 ‘대상 및 주시 대상’을 켜고 /reload 하면 VuloUI가 대상/주시 대상 프레임을 옮길 수 있습니다.",
    ["Dark Mode"] = "어두운 모드",
    ["Darkens and desaturates Blizzard's default UI artwork (unit frames, minimap, action bars) to a neutral dark tone. Keeps Blizzard's frames — it just re-tints them."] = "Blizzard 기본 UI 이미지(유닛 프레임, 미니맵, 행동 단축바)를 어둡고 채도가 낮은 중립 색조로 바꿉니다. Blizzard 프레임은 그대로 두고 색조만 다시 입힙니다.",
    ["|cffaaaaaaDarkens and desaturates Blizzard's default artwork — unit frames, minimap and action bars — to a neutral dark tone. Reversible: turn it off and the gold look returns.|r"] = "|cffaaaaaaBlizzard 기본 이미지(유닛 프레임, 미니맵, 행동 단축바)를 어둡고 채도가 낮은 중립 색조로 바꿉니다. 되돌릴 수 있습니다: 끄면 원래의 금색 외형으로 돌아옵니다.|r",
    ["Look"] = "모양",
    ["Desaturate (greyscale)"] = "채도 제거 (흑백)",
    ["Strips the colour out of the artwork before tinting, for a true greyscale look. Off keeps a hint of the original hue."] = "색조를 입히기 전에 이미지의 색을 완전히 없애 진짜 흑백처럼 만듭니다. 끄면 원래 색조가 약간 남습니다.",
    ["Tint colour"] = "색조 색상",
    ["Apply to"] = "적용 대상",
    ["Unit frames"] = "유닛 프레임",
    ["Player, target, focus, pet and party frame borders."] = "플레이어, 대상, 주시 대상, 소환수, 파티 프레임 테두리.",
    ["Minimap border, compass, zoom and tracking buttons."] = "미니맵 테두리, 나침반, 확대/축소 및 추적 버튼.",
    ["Action bar artwork"] = "행동 단축바 이미지",
    ["The gryphons and the metal action-bar background."] = "그리핀 장식과 금속 재질의 행동 단축바 배경.",
    ["Action button borders"] = "행동 버튼 테두리",
    ["Also tints the border ring around every action button. Optional — leave off if it looks too flat."] = "모든 행동 버튼을 둘러싼 테두리 고리에도 색조를 입힙니다. 선택 사항입니다 — 너무 밋밋해 보이면 꺼 두세요.",
    ["Action bar dark border"] = "행동 단축바 어두운 테두리",
    ["Adds the dark Button Skin border to the action bars while Dark Mode is on (and removes it when Dark Mode turns off). You can also switch it on with Dark Mode off in the Button Skin module."] = "어두운 모드가 켜져 있는 동안 행동 단축바에 어두운 버튼 스킨 테두리를 추가합니다 (어두운 모드를 끄면 제거됩니다). 어두운 모드를 끈 상태에서는 버튼 스킨 모듈에서 켤 수 있습니다.",
    ["Bag slots"] = "가방 칸",
    ["Tints the backpack, bag and keyring button borders."] = "배낭, 가방, 열쇠 꾸러미 버튼 테두리에 색조를 입힙니다.",
    ["|cffaaaaaaNote: if the Player & Target Frame module's |cffffffffThreat glow|r is on, threat colouring takes over the target/focus border while you have aggro — that's intended.|r"] = "|cffaaaaaa참고: 플레이어 및 대상 프레임 모듈의 |cffffffff위협 수준 발광|r이 켜져 있으면 어그로를 가진 동안 위협 수준 색상이 대상/주시 대상 테두리를 대신 표시합니다 — 의도된 동작입니다.|r",
    ["|cffaaaaaaAction button borders are also managed by the Button Skin module — if that's on, it controls the buttons instead.|r"] = "|cffaaaaaa행동 버튼 테두리는 버튼 스킨 모듈에서도 관리합니다 — 그 모듈이 켜져 있으면 버튼을 그쪽에서 제어합니다.|r",
    ["Chat"] = "대화",
    ["Polishes Blizzard's chat: a dark panel with an icon sidebar, timestamps, class-coloured names, clickable links, dark tabs, idle fade and history that survives a /reload. Every part is optional."] = "Blizzard 대화창을 다듬습니다: 어두운 패널과 아이콘 사이드바, 시간 표시, 직업 색상 이름, 클릭 가능한 링크, 어두운 탭, 대기 시 흐려짐, /reload 후에도 남는 기록. 모든 항목은 선택 사항입니다.",
    ["|cffaaaaaaPolishes Blizzard's own chat — nothing is replaced, so it stays light and compatible. Every option below is independent.|r"] = "|cffaaaaaaBlizzard 기본 대화창을 다듬습니다 — 무엇도 교체하지 않으므로 가볍고 호환성이 좋습니다. 아래 설정은 각각 독립적입니다.|r",
    ["Timestamps"] = "시간 표시",
    ["Show timestamps"] = "시간 표시 사용",
    ["Prefixes each line with the time, using the game's own timestamp setting."] = "게임 자체의 시간 표시 설정을 사용해 각 줄 앞에 시간을 붙입니다.",
    ["Time format"] = "시간 형식",
    ["Names & links"] = "이름 및 링크",
    ["Class-coloured names"] = "직업 색상 이름",
    ["Colours player names by their class in say, party, raid, guild, whisper and channels."] = "일반 대화, 파티, 공격대, 길드, 귓속말, 채널에서 플레이어 이름을 직업 색상으로 표시합니다.",
    ["Clickable links"] = "클릭 가능한 링크",
    ["Turns web links into clickable links that open a copy box."] = "웹 주소를 클릭하면 복사 입력창이 열리는 링크로 바꿉니다.",
    ["Style chat tabs"] = "대화 탭 꾸미기",
    ["Flat dark tab background with an accent underline on the active tab."] = "평평한 어두운 탭 배경과 활성 탭 아래의 강조 밑줄.",
    ["Tab label size"] = "탭 글자 크기",
    ["One uniform font size for every chat tab label."] = "모든 대화 탭 이름에 동일한 글꼴 크기를 적용합니다.",
    ["Chat font size (0 = Blizzard)"] = "대화 글꼴 크기 (0 = Blizzard)",
    ["Scrollback (lines per window)"] = "스크롤 기록 (창당 줄 수)",
    ["How many lines each chat window keeps for scrolling (Blizzard default: 128). More lines use a little more memory; changing this clears the currently shown lines once."] = "각 대화창이 스크롤용으로 보관하는 줄 수입니다 (Blizzard 기본값: 128). 줄이 많을수록 메모리를 조금 더 사용하며, 이 값을 바꾸면 현재 표시된 줄이 한 번 지워집니다.",
    ["Item levels in chat links"] = "대화 링크에 아이템 레벨 표시",
    ["Appends the item level to equipment links: [Sword] becomes [Sword (45)]."] = "장비 링크에 아이템 레벨을 덧붙입니다: [검]이 [검 (45)]로 표시됩니다.",
    ["Panel opacity (%)"] = "패널 불투명도 (%)",
    ["Transparency of the dark background panel behind the chat."] = "대화창 뒤 어두운 배경 패널의 투명도입니다.",
    ["Indent wrapped lines"] = "줄바꿈된 줄 들여쓰기",
    ["Wraps long messages with continuation lines indented under the message start, for a cleaner column."] = "긴 메시지의 이어지는 줄을 메시지 시작 위치 아래로 들여써서 더 깔끔한 단으로 정렬합니다.",
    ["Copy button"] = "복사 버튼",
    ["A small button above the chat that opens a copyable text box of the current window."] = "현재 창의 내용을 복사할 수 있는 입력창을 여는 작은 버튼을 대화창 위에 표시합니다.",
    ["Idle fade"] = "대기 시 흐려짐",
    ["Fade chat when idle"] = "대기 시 대화창 흐리게",
    ["Dims the chat after a while with no activity. A new message, hovering it or typing brings it back."] = "활동이 없으면 잠시 뒤 대화창을 흐리게 합니다. 새 메시지가 오거나 마우스를 올리거나 입력하면 다시 밝아집니다.",
    ["Idle delay (seconds)"] = "대기 시간 (초)",
    ["Faded opacity (%)"] = "흐려진 상태 불투명도 (%)",
    ["History"] = "기록",
    ["Keep chat history"] = "대화 기록 유지",
    ["Remembers recent chat per character and re-shows it after a /reload."] = "캐릭터별로 최근 대화를 기억해 /reload 후 다시 보여줍니다.",
    ["Lines to keep"] = "보관할 줄 수",
    ["Clear history"] = "기록 지우기",
    ["Chat history cleared."] = "대화 기록을 지웠습니다.",
    ["--- chat history ---"] = "--- 대화 기록 ---",
    ["Copy"] = "복사",
    ["Copy chat"] = "대화 복사",
    ["Link"] = "링크",
    ["Ctrl+A to select all, Ctrl+C to copy."] = "Ctrl+A로 전체 선택, Ctrl+C로 복사합니다.",
    ["Scroll to bottom"] = "맨 아래로 이동",
    ["|cffaaaaaaThe panel, input and sidebar reposition Blizzard's chat. Turning them off here hides them immediately; a |cffffffff/reload|r restores the exact original positions.|r"] = "|cffaaaaaa패널, 입력창, 사이드바는 Blizzard 대화창의 위치를 조정합니다. 여기서 끄면 즉시 사라지며, |cffffffff/reload|r하면 원래 위치가 정확히 복원됩니다.|r",
    ["Dark background panel"] = "어두운 배경 패널",
    ["A dark panel behind the chat and input line, with the tab bar above it — one cohesive block."] = "대화창과 입력줄 뒤의 어두운 패널이며, 그 위에 탭 막대가 놓여 하나의 통일된 덩어리를 이룹니다.",
    ["Top fade"] = "상단 흐림",
    ["Fades old lines into the panel at the top edge of the chat."] = "대화창 위쪽 가장자리에서 오래된 줄을 패널 속으로 서서히 흐리게 합니다.",
    ["Icon sidebar"] = "아이콘 사이드바",
    ["A slim bar left of the chat with copy, settings, new-window and scroll-to-bottom icons."] = "대화창 왼쪽의 가느다란 막대로, 복사, 설정, 새 창, 맨 아래로 이동 아이콘이 있습니다.",
    ["Show online friends"] = "접속 중인 친구 표시",
    ["Show how many friends are online at the top of the sidebar; click the icon to open the friends list."] = "사이드바 위쪽에 접속 중인 친구 수를 표시하며, 아이콘을 클릭하면 친구 목록이 열립니다.",
    ["Friends online"] = "접속 중인 친구",
    ["New chat window"] = "새 대화창",
    ["Create new chat window"] = "새 대화창 만들기",
    ["This client can't create extra chat windows."] = "이 클라이언트에서는 대화창을 추가로 만들 수 없습니다.",
    ["Use VuloUI font"] = "VuloUI 글꼴 사용",
    ["Applies the VuloUI font to the chat text, tabs and input line."] = "대화 문자, 탭, 입력줄에 VuloUI 글꼴을 적용합니다.",
    ["Copy button (standalone)"] = "복사 버튼 (단독)",
    ["A small copy button above the chat. Off by default since the sidebar already has a copy icon; turn the sidebar off to use this instead."] = "대화창 위의 작은 복사 버튼입니다. 사이드바에 이미 복사 아이콘이 있어 기본적으로 꺼져 있으며, 사이드바를 끄고 대신 사용하세요.",
    ["Bags"] = "가방",
    ["Inventory"] = "소지품",
    ["Items"] = "아이템",
    ["Hide"] = "숨기기",
    ["Show"] = "표시",
    ["Color item levels by quality"] = "아이템 레벨을 등급 색상으로 표시",
    ["Tints the item level number in the item's quality color instead of plain white."] = "아이템 레벨 숫자를 흰색 대신 아이템 등급 색상으로 표시합니다.",
    ["%d free"] = "빈 칸 %d",
    ["|cffaaaaaaOne window for all your bags. Press your bag key (default B) to open it. Type in the search box to find items; click the sort button to tidy up. At a banker, your bank opens in a matching window.|r"] = "|cffaaaaaa모든 가방을 하나의 창에 모읍니다. 가방 단축키(기본값 B)를 누르면 열립니다. 검색란에 입력해 아이템을 찾고, 정렬 버튼을 클릭해 정리하세요. 은행원에게 가면 은행도 같은 형태의 창으로 열립니다.|r",
    ["Quality borders"] = "등급 테두리",
    ["Colour each item's border by its rarity."] = "각 아이템의 테두리를 희귀도에 따라 색칠합니다.",
    ["Item count text size"] = "아이템 개수 글자 크기",
    ["Reset bag position"] = "가방 위치 초기화",
    ["Search & sorting"] = "검색 및 정렬",
    ["Show search box"] = "검색란 표시",
    ["A search field in the window header. Dims items that don't match."] = "창 머리글의 검색란입니다. 일치하지 않는 아이템을 흐리게 표시합니다.",
    ["Show sort button"] = "정렬 버튼 표시",
    ["A sort button in the window header. Right-click it to reverse the order."] = "창 머리글의 정렬 버튼입니다. 오른쪽 클릭하면 순서가 반대로 바뀝니다.",
    ["Reverse sort order"] = "정렬 순서 반대로",
    ["Sort from low to high quality instead of high to low."] = "높은 등급에서 낮은 등급 순 대신 낮은 등급에서 높은 등급 순으로 정렬합니다.",
    ["Sort bags"] = "가방 정렬",
    ["Bank contents"] = "은행 보관 내역",
    ["Shows what your bank holds - from the last bank visit, viewable anywhere."] = "은행에 보관 중인 물품을 보여줍니다 — 마지막 은행 방문 시점 기준이며 어디서든 확인할 수 있습니다.",
    ["As of: %s"] = "기준: %s",
    ["%d free slots"] = "빈 칸 %d개",
    ["No bank visit recorded on this character yet."] = "이 캐릭터의 은행 방문 기록이 아직 없습니다.",
