    ["Crowd Control"] = "군중 제어",
    ["Addon font (default)"] = "애드온 글꼴 (기본값)",
    ["The typeface for every text on the plates (name, health, cast, auras)."] = "이름표의 모든 글자(이름, 생명력, 시전, 오라)에 사용할 글꼴입니다.",
    ["Health text size"] = "생명력 글자 크기",
    ["0 = uses the general text size."] = "0 = 일반 글자 크기 사용.",
