    ["Cast background opacity"] = "시전 배경 불투명도",
    ["0 = uses the global background opacity."] = "0 = 전체 배경 불투명도 사용.",
    ["Icon scale"] = "아이콘 크기 비율",
    ["Icon on the right"] = "아이콘 오른쪽 배치",
