    ["Icon offset Y"] = "아이콘 Y 오프셋",
    ["Shield on uninterruptible casts"] = "방해 불가 시전에 방패 표시",
    ["Tick where your interrupt becomes ready"] = "시전 방해 준비 지점 눈금",
    ["Marks the spot on the enemy cast bar where YOUR interrupt comes off cooldown — everything after the tick is kickable."] = "적 시전 바에서 자신의 시전 방해 기술이 대기시간을 마치는 지점을 표시합니다 — 눈금 이후는 모두 끊을 수 있습니다.",
    ["Tick colour"] = "눈금 색",
