    ["0 = slightly smaller than the name."] = "0 = 이름보다 조금 작게.",
    ["CC icon width"] = "군중 제어 아이콘 너비",
    ["CC icon height"] = "군중 제어 아이콘 높이",
    ["0 = square (uses the icon size)."] = "0 = 정사각형 (아이콘 크기 사용).",
    ["Cast bar width"] = "시전 바 너비",
    ["0 = match the health bar width."] = "0 = 생명력 바 너비에 맞춤.",
    ["Name offset X"] = "이름 X 오프셋",
    ["Name offset Y"] = "이름 Y 오프셋",
    ["Health text offset X"] = "생명력 글자 X 오프셋",
    ["Health text offset Y"] = "생명력 글자 Y 오프셋",
    ["Aura offset X"] = "오라 X 오프셋",
    ["Aura offset Y"] = "오라 Y 오프셋",
    ["Point shape"] = "표식 모양",
    ["Diamond"] = "마름모",
    ["Triangle"] = "삼각형",
    ["Below the bar"] = "바 아래",
    ["Above the bar"] = "바 위",
    ["Execute line"] = "마무리 일격 선",
    ["A thin marker line on the bar at the chosen health percentage (e.g. 20 for Execute)."] = "선택한 생명력 백분율 위치에 얇은 표시선을 그립니다 (예: 마무리 일격이면 20).",
    ["Execute line only on your target"] = "대상에만 마무리 일격 선 표시",
    ["Execute line colour"] = "마무리 일격 선 색",
    ["Execute line percent"] = "마무리 일격 선 백분율",
    ["Show remaining cast time"] = "남은 시전 시간 표시",
    ["Own colour while your interrupt is on cooldown"] = "시전 방해 대기 중 별도 색",
    ["Interruptible casts paint differently while YOUR interrupt ability is still on cooldown — you see at a glance whether kicking is even possible."] = "자신의 시전 방해 기술이 아직 대기시간일 때 방해 가능한 시전이 다르게 표시되어, 끊을 수 있는지 한눈에 알 수 있습니다.",
    ["Interrupt-on-cooldown colour"] = "방해 대기 중 색",
    ["Own bar colour on your target"] = "대상 지정 시 별도 바 색",
    ["Your current target's health bar uses this colour instead of reaction / class / threat colours."] = "현재 대상의 생명력 바가 반응 / 직업 / 위협 수준 색 대신 이 색을 사용합니다.",
    ["Target bar colour"] = "대상 바 색",
    ["Mouseover highlight"] = "마우스 오버 강조",
    ["Lightens the health bar of the plate under your mouse cursor."] = "마우스 커서가 올라간 이름표의 생명력 바를 밝게 표시합니다.",
    ["Target plate scale"] = "대상 이름표 크기 비율",
    ["Your target's plate is drawn this much larger (100 = off)."] = "현재 대상의 이름표를 이만큼 크게 표시합니다 (100 = 끔).",
    ["Behaviour"] = "동작",
    ["|cffaaaaaaThese are the game's own nameplate settings, changed live (not part of the profile). Not changeable in combat.|r"] = "|cffaaaaaa게임 자체의 이름표 설정이며 즉시 적용됩니다 (프로필에 저장되지 않음). 전투 중에는 변경할 수 없습니다.|r",
    ["Plate motion"] = "이름표 배치 방식",
    ["Overlapping"] = "겹침",
    ["Stacking"] = "쌓기",
    ["Stacked spacing"] = "쌓을 때 간격",
    ["Vertical distance between stacked plates (a tenth of the game value)."] = "쌓인 이름표 사이의 세로 간격입니다 (게임 값의 10분의 1).",
    ["Line-of-sight opacity"] = "시야 밖 불투명도",
    ["Opacity of plates whose unit is out of your line of sight."] = "자신의 시야에서 벗어난 대상의 이름표 불투명도입니다.",
    ["Plate view distance"] = "이름표 표시 거리",
    ["Hitbox width"] = "클릭 영역 너비",
    ["Clickable plate area (0 = the game's default). Stored in the profile."] = "이름표를 클릭할 수 있는 영역입니다 (0 = 게임 기본값). 프로필에 저장됩니다.",
    ["Hitbox height"] = "클릭 영역 높이",
    ["|cffaaaaaaWhile the key is held (or your target matches), the main bar shows the chosen bar's abilities instead. Fully secure — works in combat.|r"] = "|cffaaaaaa키를 누르고 있는 동안(또는 대상이 조건에 맞을 때) 주 단축바에 선택한 단축바의 능력이 대신 표시됩니다. 완전히 안전하며 전투 중에도 작동합니다.|r",
    ["Shift held"] = "Shift 누름",
