    ["Quick keybind mode (/vkb)"] = "빠른 단축키 지정 모드 (/vkb)",
    ["Hover an action button and press a key to bind it. Hidden bars are shown while binding."] = "행동 버튼에 마우스를 올리고 키를 누르면 지정됩니다. 지정하는 동안에는 숨겨진 단축바도 표시됩니다.",
    ["Swipe colour"] = "스와이프 색",
    ["Icon opacity on cooldown"] = "대기시간 중 아이콘 불투명도",
    ["Dims the whole icon while the ability is on cooldown (100 = off)."] = "능력이 재사용 대기시간인 동안 아이콘 전체를 어둡게 합니다 (100 = 끔).",
    ["Show cooldown numbers"] = "재사용 대기시간 숫자 표시",
    ["The game's own countdown numbers on cooldowns (a game setting, changed live)."] = "재사용 대기시간에 표시되는 게임 자체의 초읽기 숫자입니다 (게임 설정이며 즉시 적용됩니다).",
    ["|cffaaaaaaApplies to every action bar.|r"] = "|cffaaaaaa모든 행동 단축바에 적용됩니다.|r",
    ["Cooldown swipe opacity"] = "대기시간 스와이프 불투명도",
    ["How dark the cooldown sweep overlay is (0 = invisible)."] = "재사용 대기시간 스와이프 오버레이가 얼마나 어두운지 정합니다 (0 = 보이지 않음).",
    ["Desaturate icons on cooldown"] = "대기시간 중 아이콘 흑백 처리",
    ["Out-of-range colouring"] = "사정거리 밖 색 표시",
    ["Tints the whole icon while your target is out of range."] = "대상이 사정거리 밖에 있는 동안 아이콘 전체를 물들입니다.",
    ["Tooltips"] = "툴팁",
    ["Hide in combat"] = "전투 중 숨기기",
    ["Hide always"] = "항상 숨기기",
    ["A movable, resizable experience bar with rested overlay. Hidden at max level."] = "휴식 경험치 표시가 있는 이동 및 크기 조절 가능한 경험치 바입니다. 최고 레벨에서는 숨겨집니다.",
    ["A movable, resizable experience bar with rested overlay. Hidden at max level. Replaces Blizzard's bar while on."] = "휴식 경험치 표시가 있는 이동 및 크기 조절 가능한 경험치 바입니다. 최고 레벨에서는 숨겨집니다. 켜져 있는 동안 Blizzard 바를 대체합니다.",
    ["Hide Blizzard's XP / reputation bar"] = "Blizzard 경험치 / 평판 바 숨기기",
    ["Removes the leftover blue experience / reputation bar under the action bar."] = "행동 단축바 아래에 남아 있는 파란색 경험치 / 평판 바를 제거합니다.",
    ["Main bar"] = "주 단축바",
    ["Bottom left bar"] = "좌측 하단 단축바",
    ["Bottom right bar"] = "우측 하단 단축바",
    ["Right bar"] = "우측 단축바",
    ["Left bar"] = "좌측 단축바",
    ["Stance bar"] = "태세 단축바",
    ["Pet bar"] = "소환수 단축바",
    ["Takes over every action bar with its own movable frames: real combat/mouseover show-hide, scale and grid layout per bar, correct main-bar paging (druid/rogue/warrior/priest forms) and your keybinds. EXPERIMENTAL — test ability clicks and paging in combat; /reload after disabling."] = "모든 행동 단축바를 이동 가능한 자체 프레임으로 대체합니다: 실제 전투/마우스 오버 표시·숨김, 단축바별 크기 비율과 격자 배치, 올바른 주 단축바 페이지 전환(드루이드/도적/전사/사제 형태), 기존 단축키를 지원합니다. 실험적 기능 — 전투 중에 능력 클릭과 페이지 전환을 시험해 보세요. 비활성화한 뒤에는 /reload 를 실행하세요.",
    ["|cffffcc00Action Bars disabled — type /reload to fully restore the default bars.|r"] = "|cffffcc00행동 단축바 비활성화됨 — 기본 단축바를 완전히 복원하려면 /reload 를 입력하세요.|r",
    ["|cffaaaaaaTakes over every action bar with its own movable frame: real combat / mouseover show-hide, scale and grid layout per bar, correct main-bar paging (druid/rogue/warrior/priest forms) and your keybinds. EXPERIMENTAL: test ability clicks and form-switching in combat. After disabling, type /reload to fully restore Blizzard's bars.|r"] = "|cffaaaaaa모든 행동 단축바를 이동 가능한 자체 프레임으로 대체합니다: 실제 전투 / 마우스 오버 표시·숨김, 단축바별 크기 비율과 격자 배치, 올바른 주 단축바 페이지 전환(드루이드/도적/전사/사제 형태), 기존 단축키를 지원합니다. 실험적 기능: 전투 중에 능력 클릭과 형태 전환을 시험해 보세요. 비활성화한 뒤 Blizzard 단축바를 완전히 복원하려면 /reload 를 입력하세요.|r",
    ["Custom layout"] = "사용자 지정 배치",
    ["Arrange this bar's buttons in your own grid. Off keeps Blizzard's native layout."] = "이 단축바의 버튼을 원하는 격자로 배치합니다. 끄면 Blizzard 기본 배치를 유지합니다.",
    ["Buttons per row"] = "줄당 버튼 수",
    ["Button spacing"] = "버튼 간격",
    ["Reset ALL VuloClassicUI settings for every character on this account? This cannot be undone."] = "이 계정의 모든 캐릭터에 대해 VuloClassicUI의 모든 설정을 초기화합니까? 되돌릴 수 없습니다.",
    ["Swing Timer switched off: it only tracks melee auto-attacks, which this character's talents do not use."] = "공격 타이머를 끓습니다: 근접 자동 공격만 추적하는데, 이 캐릭터의 특성은 근접 공격을 사용하지 않습니다.",
    ["|cffff5555Settings migration %s failed:|r %s"] = "|cffff5555설정 이전 %s 실패:|r %s",
    ["Plays a raid warning sound the moment an opponent uses their PvP trinket."] = "상대가 PvP 장신구를 사용하는 즉시 공격대 경고음을 재생합니다.",
    ["Flashes the icon briefly when an opponent uses their PvP trinket."] = "상대가 PvP 장신구를 사용하면 아이콘이 잠긐 빛납니다.",
    ["Icon gap"] = "아이콘 간격",
    ["Distance between the icon and the bar."] = "아이콘과 바 사이의 거리입니다.",
    ["Accent colour"] = "강조 색상",
    ["Used for the bar while the fill mode is not a texture, and for channelled casts on Blizzard's own castbar."] = "채우기 방식이 텍스처가 아닐 때 바에 사용되며, 블리자드 기본 시전 바의 시전 유지 주문에도 사용됩니다.",
    ["Cast finished"] = "시전 완료",
    ["The bar flashes in this colour when a cast completes."] = "시전이 끝나면 바가 이 색으로 번쌝입니다.",
    ["Cast interrupted"] = "시전 중단",
    ["The bar flashes in this colour when a cast is interrupted or fails."] = "시전이 중단되거나 실패하면 바가 이 색으로 번쌝입니다.",
    ["Fade-in time"] = "나타나는 시간",
    ["How long an icon takes to appear. 0 makes it show instantly."] = "아이콘이 나타나는 데 걸리는 시간입니다. 0이면 즉시 표시됩니다.",
    [" and %d item(s)"] = " 및 아이템 %d개",
    ["/vlfg toggles the group board."] = "/vlfg 명령으로 그룹 게시판을 여닫습니다.",
    ["Auto-apply a lure when the pole has none"] = "낚싯대에 미띄가 없으면 자동으로 바릅니다",
    ["Auto-equip a fishing pole if none is worn"] = "낚싯대를 착용하지 않았으면 자동으로 착용",
    ["Auto-loot while fishing"] = "낚시 중 자동 획득",
